using namespace std;

struct Child {
    int v, d, p, index;
};

int main() {
    int n;
    cin >> n;
    vector<Child> q;
    for (int i = 0; i < n; ++i) {
        int vi, di, pi;
        cin >> vi >> di >> pi;
        q.push_back({vi, di, pi, i + 1});
    }

    vector<int> result;
    while (!q.empty()) {
        Child current = q[0];
        result.push_back(current.index);
        q.erase(q.begin());

        if (!q.empty()) {
            int v_val = current.v;
            for (int i = 0; i < q.size(); ++i) {
                if (i < v_val) {
                    q[i].p -= (v_val - i);
                }
            }
        }

        bool changed;
        do {
            changed = false;
            for (int pos = 0; pos < q.size(); ++pos) {
                if (q[pos].p < 0) {
                    Child removed = q[pos];
                    int dj = removed.d;
                    q.erase(q.begin() + pos);
                    for (int i = pos; i < q.size(); ++i) {
                        q[i].p -= dj;
                    }
                    changed = true;
                    break;
                }
            }
        } while (changed);
    }

    cout << result.size() << endl;
    if (!result.empty()) {
        cout << result[0];
        for (int i = 1; i < result.size(); ++i) {
            cout << " " << result[i];
        }
    }
    cout << endl;
    return 0;
