struct Child {
    int vi, di, pi;
    bool in_line = true;
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    vector<Child> children(n);
    for (int i = 0; i < n; ++i) {
        cin >> children[i].vi >> children[i].di >> children[i].pi;
    }

    deque<int> q;
    for (int i = 0; i < n; ++i) {
        q.push_back(i);
    }

    vector<int> result;
    while (!q.empty()) {
        int current_idx = q.front();
        q.pop_front();

        if (!children[current_idx].in_line) continue;

        Child& current = children[current_idx];
        result.push_back(current_idx + 1); // Store 1-based index

        int cry_volume = current.vi;
        for (int i = 0; i < n; ++i) {
            if (!children[i].in_line || i == current_idx)
                continue;
            if (cry_volume > 0) {
                children[i].pi -= cry_volume--;
            }
        }

        queue<int> to_remove;
        for (int i = 0; i < n; ++i) {
            if (children[i].in_line && children[i].pi < 0) {
                to_remove.push(i);
                children[i].in_line = false;
            }
        }

        while (!to_remove.empty()) {
            int idx = to_remove.front();
            to_remove.pop();

            int dj = children[idx].di;
            for (int i = idx + 1; i < n; ++i) {
                if (children[i].in_line) {
                    children[i].pi -= dj;
                    if (children[i].pi < 0 && !children[i].in_line) {
                        to_remove.push(i);
                        children[i].in_line = false;
                    }
                }
            }
        }
    }

    cout << result.size() << '\n';
    for (int r : result) {
        cout << r << ' ';
    }
    cout << '\n';

    return 0;
}

