    auto compute_time = [&](double wx, double wy, double max_time, double& used_time, double& x, double& y) {
        double wind_speed = sqrt(wx * wx + wy * wy);
        double dir_x = wx / (wind_speed + 1e-9);
        double dir_y = wy / (wind_speed + 1e-9);

