    long long phi = p - 1;

    map<long long, int> factors;
    long long m = phi;
    for (long long i = 2; i * i <= m; ++i) {
        while (m % i == 0) {
            factors[i]++;
            m /= i;
        }
    }
    if (m > 1) factors[m]++;

    vector<long long> divisors = {1};
