            int64_t maxx = max(x1, x2);
            horizontalSegments.push_back({(minx + maxx), y1, y2, true});
        } else { // Vertical segment
            int64_t miny = min(y1, y2);
            int64_t maxy = max(y1, y2);
            verticalSegments.push_back({x1, miny, maxy, false});
        }
    }

    // Process horizontal segments
    sort(horizontalSegments.begin(), horizontalSegments.end(), [](const Segment &a, const Segment &b) {
        return a.x < b.x;
    });

    map<int64_t, set<pair<int64_t, int64_t>>> xToYIntervals;
    for (const auto &seg : horizontalSegments) {
        xToYIntervals[seg.x].insert({seg.y1, seg.y2});
    }

    // Process vertical segments and count intersections
    sort(verticalSegments.begin(), verticalSegments.end(), [](const Segment &a, const Segment &b) {
        return a.x < b.x;
    });

