                    it = xToYIntervals[x].erase(it);
                } else {
                    ++it;
                }
            }
        }

        // Add the length of the vertical segment
        totalCells += yEnd - yStart + 1;
    }

    // Count all horizontal segments
    for (const auto &[x, intervals] : xToYIntervals) {
        for (const auto &[y1, y2] : intervals) {
            totalCells += y2 - y1 + 1;
        }
    }

    cout << totalCells << "\n";
    return 0;
}

