    vector<vector<int>> st(max_level + 1, vector<int>(n));
    for (int i = 0; i < n; ++i) {
        st[0][i] = a[i];
    }
    for (int k = 1; k <= max_level; ++k) {
        for (int i = 0; i + (1 << k) - 1 < n; ++i) {
            st[k][i] = max(st[k-1][i], st[k-1][i + (1 << (k-1))]);
        }
    }
    return st;
}

int get_range_min(int l, int r, vector<vector<int>>& min_st) {
    if (l > r) return INT_MAX;
    int len = r - l + 1;
    int k = 0;
    while ((1 << (k+1)) <= len) k++;
    int j = 1 << k;
    return min( min_st[k][l], min_st[k][r - j + 1] );
}

int get_range_max(int l, int r, vector<vector<int>>& max_st) {
    if (l > r) return INT_MIN;
    int len = r - l + 1;
    int k = 0;
    while ((1 << (k+1)) <= len) k++;
    int j = 1 << k;
    return max( max_st[k][l], max_st[k][r - j + 1] );
}

int find_position(int l, int r, int x, vector<vector<int>>& min_st, vector<vector<int>>& max_st) {
    int current_l = l, current_r = r;
    while (current_l < current_r) {
        int mid = (current_l + current_r) / 2;
        int len_left = mid - current_l + 1;
        int k_left = 0;
        while ((1 << (k_left + 1)) <= len_left) k_left++;
        int j_left = 1 << k_left;
        int a1 = current_l;
        int a2 = mid - j_left + 1;
        int min_left = min( min_st[k_left][a1], min_st[k_left][a2] );
        int max_left = max( max_st[k_left][a1], max_st[k_left][a2] );
        if (min_left != x || max_left != x) {
            current_r = mid;
        } else {
            current_l = mid + 1;
        }
    }
    return current_l;
}

