    void build(int node, int l, int r) {
        if (l == r) {
            tree[node] = a[l];
        } else {
            int mid = (l + r) / 2;
            build(2*node, l, mid);
            build(2*node+1, mid+1, r);
            tree[node] = max(tree[2*node], tree[2*node+1]);
        }
    }

    int query_max(int node, int l, int r, int ql, int qr) {
        if (r < ql || l > qr) return -1;
        if (ql <= l && r <= qr) return tree[node];
        int mid = (l + r) / 2;
        int left = query_max(2*node, l, mid, ql, qr);
        int right = query_max(2*node+1, mid+1, r, ql, qr);
        return max(left, right);
    }

    int get_max(int ql, int qr) {
        return query_max(1, 1, n, ql, qr);
    }
};

int find_pos(int l, int r, int x, SegmentTreeMin &min_tree, SegmentTreeMax &max_tree, vector<int> &a) {
    if (l == r) return l;
