#include <bits/stdc++.h>
using namespace std;

int get_min(int l, int r, vector<vector<int>>& st) {
    int len = r - l + 1;
    int k = 0;
    while ((1 << (k+1)) <= len) ++k;
    int val1 = st[k][l];
    int val2 = st[k][r - (1 << k) + 1];
    return min(val1, val2);
}

int get_max(int l, int r, vector<vector<int>>& st) {
    int len = r - l + 1;
    int k = 0;
    while ((1 << (k+1)) <= len) ++k;
    int val1 = st[k][l];
    int val2 = st[k][r - (1 << k) + 1];
    return max(val1, val2);
}

int find_position(int l, int r, int x, vector<int>& a, vector<vector<int>>& st_min, vector<vector<int>>& st_max) {
    int cur_l = l, cur_r = r;
    while (cur_l <= cur_r) {
        if (a[cur_l] != x) return cur_l;
        if (a[cur_r] != x) return cur_r;
        int mid = (cur_l + cur_r) / 2;
        if (a[mid] != x) return mid;
        int left_min = get_min(cur_l, mid, st_min);
        int left_max = get_max(cur_l, mid, st_max);
        if (left_min != x || left_max != x) {
            cur_r = mid;
        } else {
            cur_l = mid + 1;
        }
    }
    return -1;
}

