        long long len = stoll(s.substr(0, pos));
        char c = s.substr(pos+1, 1)[0];
        blocks.push_back({len, c});
    }
    return blocks;
}

vector<int> compute_prefix_function(const string& s) {
    int n = s.size();
    vector<int> pi(n, 0);
    for (int i=1; i < n; ++i) {
        int j = pi[i-1];
        while (j > 0 && s[i] != s[j]) {
            j = pi[j-1];
        }
        if (s[i] == s[j]) {
            j++;
        }
        pi[i] = j;
    }
    return pi;
}

vector<int> kmp_search(const string& text, const string& pattern, const vector<int>& pi) {
    vector<int> occurrences;
    int j = 0;
    for (int i=0; i < (int)text.size(); ++i) {
        while (j > 0 && text[i] != pattern[j]) {
            j = pi[j-1];
        }
        if (text[i] == pattern[j]) {
            ++j;
        }
        if (j == (int)pattern.size()) {
            occurrences.push_back(i - j + 1);
            j = pi[j-1];
        }
    }
    return occurrences;
}

