using namespace std;

const int MAX = 200005;

struct Block {
    long long len;
    char ch;
};

vector<Block> t_blocks, s_blocks;

// KMP preprocessing
vector<int> kmp_preprocess(const string& pattern) {
    int m = pattern.size();
    vector<int> lps(m, 0);
    int len = 0;
    for (int i = 1; i < m;) {
        if (pattern[i] == pattern[len]) {
            len++;
            lps[i] = len;
            i++;
        } else {
            if (len != 0) {
                len = lps[len - 1];
            } else {
                lps[i++] = 0;
            }
        }
    }
    return lps;
}

// KMP search
vector<int> kmp_search(const string& text, const string& pattern, const vector<int>& lps) {
    vector<int> occurrences;
    int n = text.size(), m = pattern.size();
    int i = 0, j = 0;
    while (i < n) {
        if (pattern[j] == text[i]) {
            i++;
            j++;
            if (j == m) {
                occurrences.push_back(i - j);
                j = lps[j - 1];
            }
        } else {
            if (j != 0) {
                j = lps[j - 1];
            } else {
                i++;
            }
        }
    }
    return occurrences;
}

int main() {
