using namespace std;

unordered_map<long long, int> freq;
map<pair<long long, long long>, int> memo;

int dfs(long long a, long long b) {
    if (freq[a] == 0 || freq[b] == 0)
        return 2;
    pair<long long, long long> key = {a, b};
    if (memo.count(key))
        return memo[key];

    freq[a]--;
    freq[b]--;
    int res = 2 + dfs(b, a + b);
    freq[a]++;
    freq[b]++;

    return memo[key] = res;
}

