    if (visited[len]) return false;
    visited[len] = 1;

    if (len >= 2) {
        count_map[a]--;
        if (count_map[a] == 0) count_map.erase(a);
        count_map[b]--;
        if (count_map[b] == 0) count_map.erase(b);
    }

    long long next = a + b;
    if (count_map.count(next)) {
        if (dfs(b, next, len + 1)) return true;
    }

    if (len >= 2) {
        count_map[a]++;
        count_map[b]++;
    }
    return len;
}

