    vector<double> C(n);
    for (int i = 0; i < n; ++i) {
        C[i] = max_p[i] + min_p[i];
    }

    vector<double> prefix_sum(n);
    prefix_sum[0] = C[0];
    for (int i = 1; i < n; ++i) {
        prefix_sum[i] = prefix_sum[i-1] + C[i];
    }

    vector<double> a(n);
    double A_prev = 0.0;
    const double eps = 1e-8;

    for (int i = 0; i < n; ++i) {
        double S_C_prev;
        if (i == 0) {
            S_C_prev = 0.0;
        } else {
            S_C_prev = prefix_sum[i-1];
        }
        double P = S_C_prev + C[i] - 2.0 * A_prev;
        double Q = max_p[i] - A_prev * C[i];
        double D = P * P - 4.0 * Q;
        double sqrtD = sqrt(D);

        double root1 = (P + sqrtD) / 2.0;
        double root2 = (P - sqrtD) / 2.0;

        double candidate = 0.0;
        bool found = false;

        for (int k = 0; k < 2; ++k) {
            double current_candidate = (k == 0 ? root1 : root2);
            if (current_candidate < -eps) continue;
            if (current_candidate > C[i] + eps) continue;
            double A_current = A_prev + current_candidate;
            if (A_current > prefix_sum[i] + eps) continue;
            candidate = current_candidate;
