map<string, long long> memo;

string get_suffix(long long y, int len) {
    long long mod = 1;
    for (int i = 0; i < len; ++i) mod *= 10;
    long long val = y % mod;
    string s = to_string(val);
    while (s.size() < len) {
        s = "0" + s;
    }
    return s;
}

long long find_year(const string& s) {
    if (memo.find(s) != memo.end()) {
        return memo[s];
    }
    int len_s = s.size();
    long long remainder = 0;
    for (char c : s) {
        remainder = remainder * 10 + (c - '0');
    }
    long long base = 1;
    for (int i = 0; i < len_s; ++i) {
        base *= 10;
    }
    long long current = 1989;
    long long current_mod = current % base;
    long long diff = (remainder - current_mod + base) % base;
    long long y_candidate = current + diff;

    while (true) {
        bool valid = true;
        for (int i = 1; i < len_s; ++i) {
            long long mod_i = 1;
            for (int j = 0; j < i; ++j) mod_i *= 10;
            long long val_i = y_candidate % mod_i;
            string s_i;
            if (val_i == 0 && i > 0) {
                s_i = string(i, '0');
