                while (s_i.size() < i) {
                    s_i = "0" + s_i;
                }
            }
            long long year_i = find_year(s_i);
            if (year_i >= y_candidate) {
                valid = false;
                break;
            }
        }
        if (valid) {
            memo[s] = y_candidate;
            return y_candidate;
        }
        // Try next candidate
        y_candidate += base;
    }
}

