using namespace std;

map<string, long long> memo;

long long compute_power(int len) {
    long long res = 1;
    for (int i = 0; i < len; ++i) {
        res *= 10;
    }
    return res;
}

long long find_year(const string& s, map<string, long long>& memo) {
    if (memo.count(s)) {
        return memo[s];
    }

    int len_s = s.length();
    long long M = compute_power(len_s);
    long long R = stoll(s);
    long long X = 1989;
    long long remainder_x = X % M;
    long long delta = (R - remainder_x + M) % M;
    long long Y_candidate = X + delta;

    while (true) {
        bool valid = true;
        for (int l = 1; l < len_s; ++l) {
            long long mod_val = compute_power(l);
            long long rem = Y_candidate % mod_val;
            string suffix_l = to_string(rem);
            while (suffix_l.length() < l) {
                suffix_l = "0" + suffix_l;
            }
            long long Y_l = find_year(suffix_l, memo);
            if (Y_l >= Y_candidate) {
                valid = false;
                break;
            }
        }
        if (valid) {
            memo[s] = Y_candidate;
            return Y_candidate;
        }
        Y_candidate += M;
    }
}

