unordered_map<string, long long> abbr_to_year;
unordered_set<string> used_abbrs;
long long max_simulated_year = 1988; // Initially, so first year to process is 1989

string get_last_digits(long long Y, int k) {
    long long mod_val = 1;
    for (int i = 0; i < k; ++i) {
        mod_val *= 10;
    }
    long long num = Y % mod_val;
    string s = to_string(num);
    while (s.size() < k) {
        s = "0" + s;
    }
    return s;
}

void generate_abbr_for_year(long long Y) {
    for (int k = 1; ; ++k) {
        string s_k = get_last_digits(Y, k);
        if (used_abbrs.find(s_k) == used_abbrs.end()) {
            used_abbrs.insert(s_k);
            abbr_to_year[s_k] = Y;
            return;
        }
    }
}

void simulate_years(long long start_year, long long end_year) {
    if (start_year > end_year) return;
    for (long long Y = start_year; Y <= end_year; ++Y) {
        generate_abbr_for_year(Y);
    }
    max_simulated_year = max(max_simulated_year, end_year);
}

long long find_next_candidate(const string& s, long long current_max_year) {
    int L = s.length();
    long long s_num = stoll(s);
    long long mod_val = 1;
    for (int i = 0; i < L; ++i) mod_val *= 10;
    long long base = current_max_year + 1;
    long long remainder = base % mod_val;
    long long desired_mod = s_num;
    long long diff = (desired_mod - remainder + mod_val) % mod_val;
    long long Y_candidate = base + diff;
    while (true) {
        string candidate_suffix = get_last_digits(Y_candidate, L);
        if (candidate_suffix == s) {
            return Y_candidate;
        }
        Y_candidate += mod_val;
    }
}

