#include <bits/stdc++.h>
using namespace std;

long long compute_min_year(const string& suffix) {
    int k = suffix.length();
    long long s_num = stoll(suffix);
    long long m = 1;
    for (int i = 0; i < k; ++i) {
        m *= 10;
    }
    long long base = s_num;
    if (base >= 1989) {
        return base;
    } else {
        long long diff = 1989 - base;
        long long times = (diff + m - 1) / m;
        long long candidate = base + times * m;
        return candidate;
    }
}

int main() {
    int n;
    cin >> n;
    for (int q = 0; q < n; ++q) {
        string abbrev;
        cin >> abbrev;
        size_t pos = abbrev.find("'");
        string suffix = abbrev.substr(pos + 1);
        int k = suffix.length();
        long long m = 1;
        for (int i = 0; i < k; ++i) {
            m *= 10;
        }
        long long s_num = stoll(suffix);
        long long base = s_num;
        long long candidate;
        if (base >= 1989) {
            candidate = base;
        } else {
            long long diff = 1989 - base;
            long long times = (diff + m - 1) / m;
            candidate = base + times * m;
        }
        while (true) {
            bool valid = true;
            for (int i = 1; i < k; ++i) {
                long long pow_i = 1;
                for (int j = 0; j < i; ++j) {
                    pow_i *= 10;
                }
                long long mod_val = candidate % pow_i;
                string s_i;
