using namespace std;

vector<string> split(const string& s, char delimiter) {
    vector<string> tokens;
    string token;
    istringstream tokenStream(s);
    while (getline(tokenStream, token, delimiter)) {
        tokens.push_back(token);
    }
    return tokens;
}

int main() {
    string line;
    getline(cin, line);
    size_t eq_pos = line.find(" = ");
    string left_part = line.substr(0, eq_pos);
    string right_part = line.substr(eq_pos + 3);
    long long n = stoll(right_part);

    istringstream iss(left_part);
    vector<string> left_tokens;
    string token;
    while (getline(iss, token, ' ')) {
        left_tokens.push_back(token);
    }

    vector<int> coefficients;
    coefficients.push_back(1);
    for (size_t i = 1; i < left_tokens.size(); i += 2) {
        string op = left_tokens[i];
        coefficients.push_back((op == "+") ? 1 : -1);
    }

    long long S = accumulate(coefficients.begin(), coefficients.end(), 0LL);
    if (S > n) {
        cout << "Impossible\n";
        return 0;
    }

    long long sum_positive = 0;
    for (int c : coefficients) {
        if (c > 0) sum_positive += c;
    }

    long long max_sum = S + sum_positive * (n - 1);
    if (n > max_sum) {
        cout << "Impossible\n";
        return 0;
    }

    vector<long long> values(coefficients.size(), 1LL);
    long long D = n - S;
    for (size_t i = 0; i < coefficients.size(); ++i) {
        if (coefficients[i] <= 0) continue;
        if (D == 0) break;
        long long add = min(D, (long long)(n - 1));
        values[i] += add;
        D -= add;
    }

    int idx = 0;
    for (string& t : left_tokens) {
        if (t == "?") {
            stringstream val;
            val << values[idx];
            t = val.str();
            ++idx;
        }
    }

    string output;
    for (const string& t : left_tokens) {
        output += t + " ";
    }
    output = output.substr(0, output.length() - 1);
    output += " = " + right_part;

    cout << "Possible\n" << output << endl;

    return 0;
}

