#include <bits/stdc++.h>
using namespace std;

#define MAXN 100005
#define LOG 20

int a[MAXN];
int st[LOG][MAXN];
int log_table[MAXN];

void build_st(int n) {
    for (int i = 1; i <= n; ++i) {
        st[0][i] = i;
    }
    for (int k = 1; k < LOG; ++k) {
        for (int i = 1; i + (1 << k) - 1 <= n; ++i) {
            int j = i + (1 << (k - 1));
            int idx1 = st[k - 1][i];
            int idx2 = st[k - 1][j];
            if (a[idx1] > a[idx2]) {
                st[k][i] = idx1;
            } else if (a[idx1] < a[idx2]) {
                st[k][i] = idx2;
            } else {
                st[k][i] = max(idx1, idx2);
            }
        }
    }
}

int query_st(int L, int R) {
    int len = R - L + 1;
    int k = log_table[len];
    int offset = 1 << k;
    int a1 = st[k][L];
    int a2 = st[k][R - offset + 1];
    if (a[a1] > a[a2]) return a1;
    if (a[a1] < a[a2]) return a2;
    return max(a1, a2);
}

int main() {
    int n;
    cin >> n;
    for (int i = 1; i < n; ++i) {
        cin >> a[i];
    }
    a[n] = 0;

    log_table[1] = 0;
    for (int i = 2; i <= n; ++i) {
        log_table[i] = log_table[i / 2] + 1;
    }

    build_st(n);

    long long dp[MAXN];
    dp[n] = 0;
    for (int i = n - 1; i >= 1; --i) {
        int L = i + 1;
        int R = a[i];
        int next_i = query_st(L, R);
        dp[i] = dp[next_i] + (long long)(n - i) - (a[i] - next_i);
    }

    long long total = 0;
    for (int i = 1; i < n; ++i) {
        total += dp[i];
    }

    cout << total << endl;
    return 0;
}

