using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);
    int n;
    cin >> n;
    vector<long long> a(n + 1, 0); // a[1..n-1]
    for (int i = 1; i < n; i++) {
        cin >> a[i];
    }

    // Build sparse table for range max index
    int maxn = n - 1;
    if (maxn == 0) {
        cout << 0 << endl;
        return 0;
    }
    int log_table = 0;
    while ((1 << log_table) <= maxn) log_table++;
    log_table--;
    int max_level = log_table;
    vector<vector<int>> st(log_table + 1, vector<int>(maxn + 1, 0));
    // Initialize st[0]
    for (int i = 1; i <= maxn; i++) {
        st[0][i] = i;
    }
    // Build st
    for (int j = 1; j <= log_table; j++) {
        for (int i = 1; i + (1 << j) - 1 <= maxn; i++) {
            int prev = 1 << (j - 1);
            int idx1 = st[j - 1][i];
            int idx2 = st[j - 1][i + prev];
            if (a[idx1] >= a[idx2]) {
                st[j][i] = idx1;
            } else {
                st[j][i] = idx2;
            }
        }
    }

    vector<long long> dp_sum(n + 1, 0);
    for (int i = n - 1; i >= 1; i--) {
        int l = i + 1;
        int r_val = a[i];
        int r = min(r_val, n - 1);
        int k;
        if (l > r) {
            k = r_val;
        } else {
            int len = r - l + 1;
            int k_log = 31 - __builtin_clz(len);
            int offset = 1 << k_log;
            int r2 = r - offset + 1;
            int idx1 = st[k_log][l];
            int idx2 = st[k_log][r2];
            if (a[idx1] >= a[idx2]) {
                k = idx1;
            } else {
                k = idx2;
            }
        }
        // Now compute dp_sum[i]
        if (k <= n - 1) {
            dp_sum[i] = (n - i) + (k - a[i]) + dp_sum[k];
        } else {
            // k is n
            dp_sum[i] = (n - i) + (k - a[i]) + 0LL;
        }
    }

    long long total = 0;
    for (int i = 1; i < n; i++) {
        total += dp_sum[i];
    }
    cout << total << endl;
    return 0;
}

