#include <bits/stdc++.h>
using namespace std;

typedef long long ll;

pair<ll, ll> solve(ll m) {
    vector<ll> cubes;
    for (ll i = 1; i * i * i <= m; ++i)
        cubes.push_back(i * i * i);

    reverse(cubes.begin(), cubes.end());

    ll max_blocks = 0, best_X = 0;
    ll n = cubes.size();

    function<void(ll, ll, ll)> dfs = [&](ll idx, ll remaining, ll blocks) {
        if (blocks <= max_blocks && remaining <= best_X) return;
        if (remaining == 0) {
            if (blocks > max_blocks || (blocks == max_blocks && best_X < remaining)) {
                max_blocks = blocks;
                best_X = remaining;
            }
            return;
        }

        for (int i = idx; i < n; ++i) {
            ll cube = cubes[i];
            if (cube > remaining) continue;
            dfs(i, remaining - cube, blocks + 1);
        }
    };

    dfs(0, m, 0);
    return {max_blocks, best_X};
}

int main() {
    ll m;
    cin >> m;
    auto res = solve(m);
    cout << res.first << " " << res.second << endl;
    return 0;
}

