#include <bits/stdc++.h>
using namespace std;

map<long long, pair<long long, long long>> memo;

long long max_cube_root(long long S) {
    long long low = 1, high = 1;
    while (high * high * high < S) {
        high *= 2;
    }
    while (low <= high) {
        long long mid = (low + high) / 2;
        long long cube = mid * mid * mid;
        if (cube == S) return mid;
        else if (cube < S) {
            low = mid + 1;
        } else {
            high = mid - 1;
        }
    }
    return high;
}

pair<long long, long long> compute(long long S) {
    if (S == 0) return make_pair(0LL, 0LL);
    if (memo.find(S) != memo.end()) return memo[S];

    long long a = max_cube_root(S);
    long long cube = a * a * a;

    // Option 1: take a^3 and proceed
    pair<long long, long long> opt1 = compute(S - cube);
    long long count1 = 1 + opt1.first;
    long long x1 = cube + opt1.second;

    // Option 2: consider the case where the first cube is a-1
    long long s2 = cube - 1;
    pair<long long, long long> opt2 = compute(s2);
    long long count2 = opt2.first;
    long long x2 = opt2.second;

    if (count1 > count2) {
        memo[S] = make_pair(count1, x1);
    } else if (count1 < count2) {
        memo[S] = make_pair(count2, x2);
    } else {
        memo[S] = (x1 > x2) ? make_pair(count1, x1) : make_pair(count2, x2);
    }

    return memo[S];
}

int main() {
    long long m;
    cin >> m;
    pair<long long, long long> res = compute(m);
    cout << res.first << " " << res.second << endl;
    return 0;
}

