long long maxCubes(long long m) {
    vector<long long> cubes;
    for (long long i = 1; ; ++i) {
        long long cube = i * i * i;
        if (cube > m)
            break;
        cubes.push_back(cube);
    }

    int n = cubes.size();
    vector<pair<int, long long>> dp(n + 1); // dp[i] = {max blocks, max volume} using first i cubes

    for (int i = 1; i <= n; ++i) {
        long long cube = cubes[i - 1];
        dp[i] = dp[i - 1]; // Initially take the previous best

        // Try to use this cube as many times as possible in the greedy way
        long long remaining = m;
        int count = 0;
        long long total = 0;
        while (remaining >= cube) {
            remaining -= cube;
            count++;
        }

        // Now try to greedily add smaller cubes after this one
        int k = i - 2;
        long long vol = cube;
        int cnt = count;
        while (k >= 0 && remaining > 0) {
            long long next_cube = cubes[k];
            if (next_cube > remaining)
                break;
            remaining -= next_cube;
            cnt++;
            vol += next_cube;
            k--;
        }

        if (cnt > dp[i].first || (cnt == dp[i].first && vol > dp[i].second)) {
            dp[i] = {cnt, vol};
        }
    }

    return dp[n].second;
}

