#include <bits/stdc++.h>
using namespace std;

vector<int> find_valid_tree(int n, vector<int>& a) {
    vector<bool> visited(n + 1, false);
    vector<int> p = a;
    vector<int> in_degree(n + 1, 0);

    for (int i = 1; i <= n; ++i) {
        if (p[i] != i)
            ++in_degree[p[i]];
    }

    queue<int> q;
    for (int i = 1; i <= n; ++i) {
        if (in_degree[i] == 0)
            q.push(i);
    }

    int root_count = 0;
    int root_candidate = -1;

    while (!q.empty()) {
        int u = q.front();
        q.pop();

        if (p[u] == u) {
            ++root_count;
            root_candidate = u;
        } else {
            int v = p[u];
            --in_degree[v];
            if (in_degree[v] == 0)
                q.push(v);
        }
    }

    if (root_count > 1) {
        // Too many roots, fix all but one
        for (int i = 1; i <= n; ++i) {
            if (p[i] == i && i != root_candidate) {
                p[i] = root_candidate;
            }
        }
    } else if (root_count == 0) {
        // No root found, assign one arbitrarily
        for (int i = 1; i <= n; ++i) {
            if (in_degree[i] > 0) {
                p[i] = i;
                break;
            }
        }
    }

    return p;
}

