int find_root(int x) {
    while (parent[x] != x) {
        parent[x] = parent[parent[x]];
        x = parent[x];
    }
    return x;
}

void union_sets(int x, int y) {
    x = find_root(x);
    y = find_root(y);
    if (x == y) return;
    if (rank_set[x] < rank_set[y])
        parent[x] = y;
    else {
        parent[y] = x;
        if (rank_set[x] == rank_set[y])
            rank_set[x]++;
    }
}

