        cin >> a[i];

    parent.assign(n + 1, 0);
    rank_set.assign(n + 1, 0);
    visited.assign(n + 1, 0);

    for (int i = 1; i <= n; ++i)
        parent[i] = i;

    // Build the initial structure and detect cycles
    vector<int> to_visit;
    for (int i = 1; i <= n; ++i) {
        if (a[i] != i && find_root(i) == find_root(a[i])) {
            to_visit.push_back(i);
        } else {
            union_sets(i, a[i]);
        }
    }

    // Collect all roots of the components
    set<int> component_roots;
    for (int i = 1; i <= n; ++i)
