    // Compute in-degree for each node
    for (int i = 1; i <= n; ++i) {
        if (p[i - 1] != i) {
            ++in_degree[p[i - 1]];
        }
    }

    queue<int> roots;
    for (int i = 1; i <= n; ++i) {
        if (in_degree[i] == 0) {
            roots.push(i);
        }
    }

    int root_count = roots.size();

    // If there is more than one root candidate, we need to fix them
    if (root_count > 1) {
        int main_root = roots.front();
        while (!roots.empty()) {
            int r = roots.front();
            roots.pop();
            if (r != main_root) {
                // Change this node's parent to main_root
                for (int i = 1; i <= n; ++i) {
                    if (p[i - 1] == r) {
                        p[i - 1] = main_root;
                        break;
                    }
                }
            }
        }
    } else if (root_count == 0) {
        // No root found, pick any node as the root
        int main_root = 1;
        for (int i = 1; i <= n; ++i) {
            if (p[i - 1] != i) {
