#include <bits/stdc++.h>
using namespace std;

vector<int> findValidTree(int n, vector<int>& a) {
    vector<int> parent(n + 1);
    for (int i = 0; i < n; ++i)
        parent[i + 1] = a[i];

    vector<bool> visited(n + 1, false);
    vector<int> roots;
    vector<int> cycles;

    for (int i = 1; i <= n; ++i) {
        if (!visited[i]) {
            int x = i;
            while (true) {
                if (x > n || visited[x]) break;
                if (x == parent[x]) {
                    visited[x] = true;
                    break;
                }
                if (find(cycles.begin(), cycles.end(), x) != cycles.end()) {
                    // Already part of a cycle
                    visited[x] = true;
                    x = parent[x];
                } else {
                    bool isCycle = false;
                    vector<int> path;
                    int y = x;
                    while (true) {
                        if (y > n || visited[y]) break;
                        if (y == x) {
                            isCycle = true;
                            break;
                        }
                        if (find(path.begin(), path.end(), y) != path.end()) {
                            isCycle = true;
                            break;
                        }
                        path.push_back(y);
                        y = parent[y];
                    }
                    if (isCycle) {
                        for (int node : path)
                            cycles.push_back(node);
                    } else {
                        for (int node : path)
                            visited[node] = true;
                    }
                    break;
                }
            }
        }
    }

    // Fix cycles
    for (int i = 0; i < (int)cycles.size(); ++i) {
        if (i == (int)cycles.size() - 1)
            parent[cycles[i]] = cycles[0];
        else
            parent[cycles[i]] = cycles[i + 1];
    }

    // Ensure there's exactly one root
    int rootCount = 0;
    int chosenRoot = 0;
    for (int i = 1; i <= n; ++i) {
        if (parent[i] == i) {
            rootCount++;
            chosenRoot = i;
        }
    }

    if (rootCount > 1) {
        for (int i = 2; i <= n; ++i) {
            if (parent[i] == i) {
                parent[i] = chosenRoot;
            }
        }
    } else if (rootCount == 0) {
        parent[n] = n;
    }

    return vector<int>(parent.begin() + 1, parent.end());
}

