ll L;
int s, t;

vector<ll> dijkstra_full(int n, vector<vector<pair<int, ll>>> &graph, int start) {
    vector<ll> dist(n, 1e18);
    dist[start] = 0;
    priority_queue<pii, vector<pii>, greater<pii>> pq;
    pq.push({0, start});

    while (!pq.empty()) {
        ll d = pq.top().first;
        int u = pq.top().second;
        pq.pop();
        if (d > dist[u]) continue;
        for (auto [v, w] : graph[u]) {
            if (dist[v] > d + w) {
                dist[v] = d + w;
                pq.push({dist[v], v});
            }
        }
    }
    return dist;
}

vector<vector<pair<int, ll>>> build_graph(int n, const vector<Edge>& edges, ll zero_weight) {
    vector<vector<pair<int, ll>>> graph(n);
    for (const Edge& e : edges) {
        ll w = (e.original_w == 0) ? zero_weight : e.original_w;
        graph[e.u].push_back({e.v, w});
        graph[e.v].push_back({e.u, w});
    }
    return graph;
}

