    vector<vector<pair<int, ll>>> graph_max = build_graph(n, edges, 1e18);
    vector<ll> dist_max = dijkstra_full(n, graph_max, s);
    if (dist_max[t] < L) {
        cout << "NO" << endl;
        return 0;
    }

