#include <bits/stdc++.h>
using namespace std;

long long countOnes(long long K) {
    long long count = 0;
    for (long long i = 0; (1LL << i) <= K; ++i) {
        long long pow2 = 1LL << i;
        long long full_cycles = K / (pow2 * 2);
        long long partial = max(0LL, K % (pow2 * 2) - pow2);
        count += (full_cycles * pow2 + partial);
    }
    return count;
}

int main() {
    long long n, c0, c1;
    cin >> n >> c0 >> c1;
    bool swapped_cost = false;
    if (c0 > c1) {
        swap(c0, c1);
        swapped_cost = true;
    }
    // compute m
    long long m = 0;
    long long power = 1;
    while (power < n) {
        power *= 2;
        m++;
    }
    long long full = power / 2;
    long long extra = n - full;
    long long sum_y = countOnes(extra);
    long long total_zeros_full = (m-1) * full / 2;
    long long total_ones_full = total_zeros_full;
    long long total_zeros = total_zeros_full + extra * m - sum_y;
    long long total_ones = total_ones_full + sum_y + extra;
    if (swapped_cost) {
        swap(total_zeros, total_ones);
    }
    cout << (total_zeros * c0 + total_ones * c1) << endl;
    return 0;
}

