#include <bits/stdc++.h>
using namespace std;

long long compute(long long m, long long c0, long long c1, map<long long, long long>& memo) {
    if (m == 1) return 0LL;
    auto it = memo.find(m);
    if (it != memo.end()) return it->second;

    long long a = (m + 1) / 2;
    long long b = m / 2;

    long long current = a * c0 + b * c1;
    long long left = compute(a, c0, c1, memo);
    long long right = compute(b, c0, c1, memo);

    memo[m] = current + left + right;
    return memo[m];
}

int main() {
    long long n, c0, c1;
    cin >> n >> c0 >> c1;

    if (c0 > c1) {
        swap(c0, c1);
    }

    map<long long, long long> memo;
    long long result = compute(n, c0, c1, memo);
    cout << result << endl;

