        // Assign more bits with cost c0
        long long num_ones = n / 2;
        long long num_zeros = n - num_ones;
        total_bits = num_zeros * c0 + num_ones * c1;
    } else {
        // Assign more bits with cost c1
        long long num_zeros = n / 2;
        long long num_ones = n - num_zeros;
        total_bits = num_zeros * c0 + num_ones * c1;
    }

    cout << total_bits << endl;
    return 0;
}

