    vector<bool> result(n + 1, false);
    for (int i = 1; i <= n; ++i) {
        if (visited[i] == 0) {
            vector<int> path;
            unordered_map<int, int> node_index;
            int current = i;
            bool done = false;
            while (!done) {
                if (current < 1 || current > n) {
                    for (int node : path) {
                        visited[node] = 2;
                        result[node] = true;
                    }
                    done = true;
                } else if (visited[current] == 1) {
                    int idx = node_index[current];
                    for (int j = idx; j < path.size(); ++j) {
                        int node = path[j];
                        visited[node] = 2;
                        result[node] = false;
                    }
                    for (int j = 0; j < idx; ++j) {
                        int node = path[j];
                        visited[node] = 2;
                        result[node] = false;
                    }
                    done = true;
                } else if (visited[current] == 2) {
                    bool res = result[current];
                    for (int node : path) {
                        visited[node] = 2;
                        result[node] = res;
