        if (visited[i]) continue;
        int pos = i;
        bool cycle = false;
        while (pos >= 0 && pos < n && !visited[pos]) {
            visited[pos] = true;
            if (s[pos] == '>') {
                pos++;
            } else {
                pos--;
            }
        }
        if (pos < 0 || pos >= n) {
            // All positions in the path lead to falling out
            for (int j = i; j < n && !visited[j]; ++j) {
                if (s[j] == '>') {
                    int next = j + 1;
                    if (next >= n) {
                        result.push_back(j);
                    } else {
                        q.push(j);
                    }
                } else {
                    int next = j - 1;
                    if (next < 0) {
                        result.push_back(j);
                    } else {
                        q.push(j);
                    }
                }
            }
        }
    }

    while (!q.empty()) {
        int curr = q.front();
        q.pop();
        if (s[curr] == '>') {
