#include <bits/stdc++.h>
using namespace std;

struct Student {
    int a, b, idx;
};

bool compare_programming(const Student &x, const Student &y) {
    if (x.a != y.a) return x.a > y.a;
    return x.b < y.b;
}

bool compare_sports(const Student &x, const Student &y) {
    if (x.b != y.b) return x.b > y.b;
    return x.idx < y.idx;
}

int main() {
    int n, p, s;
    cin >> n >> p >> s;
    vector<int> a(n);
    vector<int> b(n);
    for (int i = 0; i < n; ++i) cin >> a[i];
    for (int i = 0; i < n; ++i) cin >> b[i];
    vector<Student> students(n);
    for (int i = 0; i < n; ++i) {
        students[i] = {a[i], b[i], i + 1};
    }
    sort(students.begin(), students.end(), compare_programming);
    vector<Student> prog = vector<Student>(students.begin(), students.begin() + p);
    vector<Student> remaining(students.begin() + p, students.end());
    sort(remaining.begin(), remaining.end(), compare_sports);
    vector<Student> sports(remaining.begin(), remaining.begin() + s);
    long long total = 0;
    for (Student s : prog) total += s.a;
    for (Student s : sports) total += s.b;
    cout << total << endl;
    for (int i = 0; i < p; ++i) {
        if (i) cout << " ";
        cout << prog[i].idx;
    }
    cout << endl;
    for (int i = 0; i < s; ++i) {
        if (i) cout << " ";
        cout << sports[i].idx;
    }
    cout << endl;
    return 0;
}

