    for (int i=2; i<=n; ++i) {
        int p; long long w;
        cin >> p >> w;
        tree[p].push_back( {i, w} );
    }
    // compute depth
    vector<long long> depth(n+1, 0);
    // BFS
    queue<int> q;
    q.push(1);
    while (!q.empty()) {
        int u = q.front(); q.pop();
        for (auto [v, w] : tree[u]) {
            depth[v] = depth[u] + w;
            q.push(v);
        }
    }
    // post-order traversal with small-to-large
    vector<vector<long long>> lists(n+1);
    vector<int> ans(n+1, 0);
    stack<pair<int, bool>> s; // node, processed?
    s.push( {1, false} );
    while (!s.empty()) {
        auto p = s.top();
        s.pop();
        int u = p.first;
        bool processed = p.second;
        if (!processed) {
            s.push( {u, true} );
            // push children in reverse order to process in order
            for (int i = (int)tree[u].size()-1; i >=0; --i) {
                int v = tree[u][i].first;
                s.push( {v, false} );
            }
        } else {
            // initialize list for u
            lists[u].clear();
            lists[u].push_back( depth[u] - a[u] );
            // merge children's lists
            for (auto [v, w] : tree[u]) {
                // merge lists[v] into lists[u]
                if (lists[v].size() > lists[u].size()) {
                    swap(lists[u], lists[v]);
                }
                // now merge lists[v] into lists[u]
                vector<long long>& a_vec = lists[u];
                vector<long long>& b_vec = lists[v];
                vector<long long> merged;
                merged.reserve(a_vec.size() + b_vec.size());
                merge(a_vec.begin(), a_vec.end(), b_vec.begin(), b_vec.end(), back_inserter(merged));
                a_vec.swap(merged);
                // clear the b_vec to save memory
                b_vec.clear();
            }
            // compute answer for u
            long long target = depth[u];
            auto it = upper_bound(lists[u].begin(), lists[u].end(), target);
            int count = it - lists[u].begin();
            ans[u] = count - 1;
