#include <bits/stdc++.h>
using namespace std;

vector<long long> depth;
vector<int> in_time, out_time;

struct SegmentTree {
    vector<vector<long long>> tree;
    int size;

    SegmentTree(int n, vector<long long>& data) {
        int s = 1;
        while (s < n) s <<= 1;
        size = s;
        tree.resize(2 * size);
        // Initialize leaves
        for (int i = 0; i < n; ++i) {
            tree[s + i] = { data[i] };
        }
        // Fill leaves with empty vectors if n < s
        for (int i = n; i < s; ++i) {
            tree[s + i] = {};
        }
        // Build the tree
        for (int i = s - 1; i >= 1; --i) {
            merge(tree[2*i].begin(), tree[2*i].end(), tree[2*i+1].begin(), tree[2*i+1].end(), back_inserter(tree[i]));
        }
    }

    int query(int l, int r, long long X) {
        return query_helper(1, 0, size-1, l, r, X);
    }

private:
    int query_helper(int node, int node_l, int node_r, int l, int r, long long X) {
        if (node_r < l || r < node_l) return 0;
        if (l <= node_l && node_r <= r) {
            auto it = upper_bound(tree[node].begin(), tree[node].end(), X);
            return distance(tree[node].begin(), it);
