#include <bits/stdc++.h>
using namespace std;

struct FenwickTree {
    vector<long long> tree;
    int size;

    FenwickTree(int n) {
        size = n + 2;
        tree.assign(size, 0);
    }

    void update(int idx, long long delta) {
        while (idx < size) {
            tree[idx] += delta;
            idx += idx & -idx;
        }
    }

    long long query(int idx) {
        long long res = 0;
        while (idx > 0) {
            res += tree[idx];
            idx -= idx & -idx;
        }
        return res;
    }

    void range_add(int l, int r, long long delta) {
        update(l, delta);
        update(r + 1, -delta);
    }

    long long get(int idx) {
        return query(idx);
    }
};

vector<vector<pair<int, long long>>> children;
vector<long long> depth;
vector<long long> a;
vector<int> ans;
vector<long long> stack_depths;
FenwickTree* ft;

void dfs(int node) {
    long long T = depth[node] - a[node];
    int m = stack_depths.size();
    int idx = lower_bound(stack_depths.begin(), stack_depths.end(), T) - stack_depths.begin();
    int l = idx + 1;
    int r = m;
    if (l <= r) {
        ft->range_add(l, r, 1);
    }

    stack_depths.push_back(depth[node]);
    int pos_in_stack = stack_depths.size();

    for (auto [child, w] : children[node]) {
        depth[child] = depth[node] + w;
        dfs(child);
    }

    if (l <= r) {
        ft->range_add(l, r, -1);
    }

    ans[node] = ft->get(pos_in_stack);

    stack_depths.pop_back();
}

int main() {
