            int x = i;
            while (!visited[x]) {
                visited[x] = true;
                cycle.push_back(x);
                x = p[x];
            }

            bool has_odd_length = (cycle.size() % 2 == 1);
            int required_flips = 0;

            for (int x : cycle) {
                if (b[x] == 0) required_flips++;
            }

            // If the cycle length is odd, we must flip exactly one bit in it.
            // Otherwise, we can choose to flip zero or two bits (or more even number)
            // to ensure that each element is flipped an odd number of times over the cycle.

