                    total_changes += 1;
                } else {
                    total_changes += min(required_flips, (int)cycle.size() - required_flips);
                }
            } else {
                // Even-length cycle: no constraint on flips
                total_changes += min(required_flips, (int)cycle.size() - required_flips);
            }
        }
    }

