    string name;
    string type;
    int bonus;
    string home;
};

int main() {
    int n;
    cin >> n;
    vector<Item> items(n);
    for (int i = 0; i < n; ++i) {
        cin >> items[i].name >> items[i].cls >> items[i].atk >> items[i].def >> items[i].res >> items[i].size;
    }
    int k;
    cin >> k;
    vector<Resident> residents(k);
    for (int i = 0; i < k; ++i) {
        cin >> residents[i].name >> residents[i].type >> residents[i].bonus >> residents[i].home;
    }

    vector<Item> weapons, armors, orbs;
    for (Item item : items) {
        if (item.cls == "weapon") {
            weapons.push_back(item);
        } else if (item.cls == "armor") {
            armors.push_back(item);
        } else if (item.cls == "orb") {
            orbs.push_back(item);
        }
    }

    Item best_weapon, best_armor, best_orb;
    vector<string> best_w_residents, best_a_residents, best_o_residents;
    int best_w_atk = -1, best_a_def = -1, best_o_res = -1;

    for (Item w : weapons) {
        for (Item a : armors) {
            for (Item o : orbs) {
                if (w.size + a.size + o.size < k) continue;

                vector<int> assignment(k, -1);
                vector<bool> assigned(k, false);

                vector<vector<int>> by_type(3);
                for (int i = 0; i < k; ++i) {
                    if (residents[i].type == "gladiator") {
                        by_type[0].push_back(i);
                    } else if (residents[i].type == "sentry") {
                        by_type[1].push_back(i);
                    } else {
                        by_type[2].push_back(i);
                    }
                }

                for (int t = 0; t < 3; ++t) {
                    auto& group = by_type[t];
                    sort(group.begin(), group.end(), [&](int a, int b) {
                        return residents[a].bonus > residents[b].bonus;
                    });
                }

                int w_slots = w.size, a_slots = a.size, o_slots = o.size;

                for (int idx : by_type[0]) {
                    if (!assigned[idx] && w_slots > 0) {
                        assignment[idx] = 0;
                        assigned[idx] = true;
                        w_slots--;
                    }
                }

                for (int idx : by_type[1]) {
                    if (!assigned[idx] && a_slots > 0) {
                        assignment[idx] = 1;
                        assigned[idx] = true;
                        a_slots--;
                    }
                }

                for (int idx : by_type[2]) {
                    if (!assigned[idx] && o_slots > 0) {
                        assignment[idx] = 2;
                        assigned[idx] = true;
                        o_slots--;
                    }
                }

                for (int i = 0; i < k; ++i) {
                    if (!assigned[i]) {
                        if (w_slots > 0) {
                            assignment[i] = 0;
                            w_slots--;
                        } else if (a_slots > 0) {
                            assignment[i] = 1;
                            a_slots--;
                        } else if (o_slots > 0) {
                            assignment[i] = 2;
                            o_slots--;
                        }
                        assigned[i] = true;
                    }
                }

                int sum_g = 0, sum_s = 0, sum_p = 0;
                for (int i = 0; i < k; ++i) {
                    if (assignment[i] == 0 && residents[i].type == "gladiator")
                        sum_g += residents[i].bonus;
                    else if (assignment[i] == 1 && residents[i].type == "sentry")
                        sum_s += residents[i].bonus;
                    else if (assignment[i] == 2 && residents[i].type == "physician")
                        sum_p += residents[i].bonus;
                }

                int current_w_atk = w.atk + sum_g;
                int current_a_def = a.def + sum_s;
                int current_o_res = o.res + sum_p;

                if (current_w_atk > best_w_atk ||
                    (current_w_atk == best_w_atk && current_a_def > best_a_def) ||
                    (current_w_atk == best_w_atk && current_a_def == best_a_def && current_o_res > best_o_res)) {

                    best_w_atk = current_w_atk;
                    best_a_def = current_a_def;
                    best_o_res = current_o_res;

                    best_weapon = w;
                    best_armor = a;
                    best_orb = o;

                    best_w_residents.clear();
                    best_a_residents.clear();
                    best_o_residents.clear();
