    int res;
    int size;
    vector<Resident> residents;

    void add_resident(const Resident& r) {
        residents.push_back(r);
    }

    bool has_space() const {
        return residents.size() < size;
    }

    int get_atk() const {
        int total = atk;
        for (const auto& r : residents) {
            if (r.type == "gladiator") {
                total += r.bonus;
            }
        }
        return total;
    }

    int get_def() const {
        int total = def;
        for (const auto& r : residents) {
            if (r.type == "sentry") {
                total += r.bonus;
            }
        }
        return total;
    }

    int get_res() const {
        int total = res;
        for (const auto& r : residents) {
            if (r.type == "physician") {
                total += r.bonus;
            }
        }
        return total;
    }

    int resident_count() const {
        return residents.size();
    }
};

bool compare_residents(const Resident& a, const Resident& b) {
