#include <bits/stdc++.h>
using namespace std;

bool dfs(int u, vector<vector<int>>& adj, vector<int>& match_to, vector<bool>& visited) {
    for (int v : adj[u]) {
        if (!visited[v]) {
            visited[v] = true;
            if (match_to[v] == -1 || dfs(match_to[v], adj, match_to, visited)) {
                match_to[v] = u;
                return true;
            }
        }
    }
    return false;
}

int main() {
    int n, m;
    cin >> n >> m;
    vector<string> grid(n);
    for (int i = 0; i < n; ++i) {
        cin >> grid[i];
    }

    vector<pair<int, int>> wolves;
    vector<pair<int, int>> pigs;
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < m; ++j) {
            if (grid[i][j] == 'W') {
                wolves.push_back({i, j});
            } else if (grid[i][j] == 'P') {
                pigs.push_back({i, j});
            }
        }
    }

    vector<vector<int>> pig_at(n, vector<int>(m, -1));
    int pig_idx = 0;
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < m; ++j) {
            if (grid[i][j] == 'P') {
                pig_at[i][j] = pig_idx++;
            }
        }
    }

    vector<vector<int>> adj(wolves.size());
    for (int w = 0; w < wolves.size(); ++w) {
        int x = wolves[w].first;
        int y = wolves[w].second;
        vector<pair<int, int>> directions = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};
        for (auto [dx, dy] : directions) {
            int nx = x + dx;
            int ny = y + dy;
            if (nx >= 0 && nx < n && ny >= 0 && ny < m) {
                if (grid[nx][ny] == 'P') {
                    adj[w].push_back(pig_at[nx][ny]);
                }
            }
        }
    }

    vector<int> match_to(pigs.size(), -1);
    int result = 0;
    for (int w = 0; w < wolves.size(); ++w) {
        vector<bool> visited(pigs.size(), false);
        if (dfs(w, adj, match_to, visited)) {
            ++result;
        }
    }

    cout << result << endl;
    return 0;
}

