int main() {
    int n, m;
    cin >> n >> m;
    vector<string> grid(n);
    for (int i = 0; i < n; ++i) {
        cin >> grid[i];
    }

    vector<pair<int, int>> wolves;
    vector<pair<int, int>> pigs;
    vector<vector<int>> pig_pos(n, vector<int>(m, -1));

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < m; ++j) {
            if (grid[i][j] == 'P') {
                pigs.push_back({i, j});
                pig_pos[i][j] = pigs.size() - 1;
            } else if (grid[i][j] == 'W') {
                wolves.push_back({i, j});
            }
        }
    }

    int num_wolves = wolves.size();
    int num_pigs = pigs.size();

    vector<vector<int>> adj(num_wolves);

    for (int w_idx = 0; w_idx < num_wolves; ++w_idx) {
        int x = wolves[w_idx].first;
        int y = wolves[w_idx].second;
        int dx[4] = {-1, 1, 0, 0};
        int dy[4] = {0, 0, -1, 1};
        for (int d = 0; d < 4; ++d) {
            int nx = x + dx[d];
            int ny = y + dy[d];
            if (nx >= 0 && nx < n && ny >= 0 && ny < m) {
                if (grid[nx][ny] == 'P') {
                    adj[w_idx].push_back(pig_pos[nx][ny]);
                }
            }
        }
    }

    vector<int> match_to(num_pigs, -1);

    function<bool(int, vector<bool>&)> dfs;
    dfs = [&](int u, vector<bool>& visited) -> bool {
        visited[u] = true;
        for (int p_idx : adj[u]) {
            if (match_to[p_idx] == -1 || (!visited[match_to[p_idx]] && dfs(match_to[p_idx], visited))) {
                match_to[p_idx] = u;
                return true;
            }
        }
        return false;
    };

    int result = 0;
    for (int w_idx = 0; w_idx < num_wolves; ++w_idx) {
        vector<bool> visited(num_wolves, false);
        if (dfs(w_idx, visited)) {
            ++result;
        }
    }

    cout << result << endl;

    return 0;
}

