using namespace std;

struct HeapElement {
    string s;
    int start;
    int len;
};

struct HeapElementCompare {
    bool operator()(const HeapElement& a, const HeapElement& b) const {
        return a.s > b.s;
    }
};

int main() {
    string s;
    cin >> s;
    long long k;
    cin >> k;
    long long n = s.size();
    long long total = n * (n + 1) / 2;
    if (k > total) {
        cout << "No such line." << endl;
        return 0;
    }
    priority_queue<HeapElement, vector<HeapElement>, HeapElementCompare> min_heap;
    for (int i = 0; i < n; ++i) {
        HeapElement e;
        e.s = string(1, s[i]);
        e.start = i;
        e.len = 1;
        min_heap.push(e);
    }
    for (int step = 0; step < k; ++step) {
        if (min_heap.empty()) {
            cout << "No such line." << endl;
            return 0;
        }
        HeapElement current = min_heap.top();
        min_heap.pop();
        if (step == k - 1) {
            cout << current.s << endl;
            return 0;
        }
        if (current.start + current.len < n) {
            char next_char = s[current.start + current.len];
            HeapElement new_e;
            new_e.s = current.s + next_char;
            new_e.start = current.start;
            new_e.len = current.len + 1;
            min_heap.push(new_e);
        }
    }
    return 0;
}

