#include <bits/stdc++.h>
using namespace std;

struct Compare {
    string s;
    Compare(string str) : s(move(str)) {}
    bool operator()(const pair<int, int>& a, const pair<int, int>& b) const {
        int i = a.first, lenA = a.second;
        int j = b.first, lenB = b.second;
        int min_len = min(lenA, lenB);
        for (int k = 0; k < min_len; ++k) {
            if (s[i + k] != s[j + k]) {
                return s[i + k] > s[j + k];
            }
        }
        return lenA > lenB;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);
    string s;
    cin >> s;
    long long k;
    cin >> k;
    int n = s.size();
    long long total = (long long)n * (n + 1) / 2;
    if (k > total) {
        cout << "No such line." << endl;
        return 0;
    }
    Compare comp(s);
    priority_queue<pair<int, int>, vector<pair<int, int>>, Compare> heap(comp, vector<pair<int, int>>());
    for (int i = 0; i < n; ++i) {
        heap.push({i, 1});
    }
    for (int step = 1; step < k; ++step) {
        auto current = heap.top();
        heap.pop();
        int start = current.first;
        int len = current.second;
        if (start + len < n) {
            heap.push({start, len + 1});
        }
    }
    auto current = heap.top();
    int start = current.first;
    int len = current.second;
    cout << s.substr(start, len) << endl;
}

