    }
    // Check if contiguous
    if (unique_vals.back() - unique_vals[0] != m - 1) {
        cout << "NO" << endl;
        return 0;
    }
    // Now check based on m
    if (m == 2) {
        // Check if counts are equal
        map<long long, int> freq;
