long long compute_ways(int L, int k) {
    if (2 * k > L) return 0LL;
    vector<long long> prev(L + 2, 0);
    prev[L] = 1;
    for (int step = 1; step <= k; ++step) {
        vector<long long> suffix_sum_prev(L + 2, 0);
        vector<long long> suffix_sum_s_prev(L + 2, 0);
        for (int j = L; j >= 0; --j) {
            suffix_sum_prev[j] = (prev[j] + suffix_sum_prev[j + 1]) % MOD;
            suffix_sum_s_prev[j] = ((static_cast<long long>(j) * prev[j]) % MOD + suffix_sum_s_prev[j + 1]) % MOD;
        }
        vector<long long> curr(L + 2, 0);
        for (int s_curr = 1; s_curr <= L; ++s_curr) {
            int s_prev_min = s_curr + 2;
