#include <bits/stdc++.h>
using namespace std;

const int MAXN = 105;
int dp[MAXN][MAXN][2]; // dp[l][r][turn] = value of game from l to r, turn: 0 for Masha (min), 1 for Petya (max)

string s;

int solve(int l, int r, int turn) {
    if (r - l + 1 == 2) {
        return (s[l] == '1' || s[l] == '?') ? 1 : 0 << 1 | (s[r] == '1' || s[r] == '?') ? 1 : 0;
    }
    if (dp[l][r][turn] != -1)
        return dp[l][r][turn];

    int res;
    if (turn == 0) { // Masha's turn: minimize
        res = INT_MAX;
        for (int i = l; i <= r; ++i) {
            int left = solve(l, i - 1, 1);
            int right = solve(i + 1, r, 1);
            int val;
            if (i == l) val = right;
            else if (i == r) val = left;
            else val = min(left >> 1, right >> 1) << 1 | max(left & 1, right & 1);
            res = min(res, val);
        }
    } else { // Petya's turn: maximize
        res = INT_MIN;
        for (int i = l; i <= r; ++i) {
            int left = solve(l, i - 1, 0);
            int right = solve(i + 1, r, 0);
            int val;
            if (i == l) val = right;
            else if (i == r) val = left;
            else val = max(left >> 1, right >> 1) << 1 | min(left & 1, right & 1);
            res = max(res, val);
        }
    }

    return dp[l][r][turn] = res;
}

void dfs(int pos, int n, vector<int>& arr, set<pair<char, char>>& outcomes) {
    if (pos == n) {
        string curr(n, ' ');
        for (int i = 0; i < n; ++i)
            curr[i] = arr[i] + '0';
        memset(dp, -1, sizeof(dp));
        int result = solve(0, n - 1, 0);
        char d1 = (result >> 1) + '0';
        char d2 = (result & 1) + '0';
        outcomes.insert({d1, d2});
        return;
    }

    if (s[pos] == '0') {
        arr[pos] = 0;
        dfs(pos + 1, n, arr, outcomes);
    } else if (s[pos] == '1') {
        arr[pos] = 1;
        dfs(pos + 1, n, arr, outcomes);
    } else {
        arr[pos] = 0;
        dfs(pos + 1, n, arr, outcomes);
        arr[pos] = 1;
        dfs(pos + 1, n, arr, outcomes);
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> s;
    int n = s.length();
    vector<int> arr(n);
    set<pair<char, char>> outcomes;

    dfs(0, n, arr, outcomes);

    for (auto p : outcomes) {
        cout << p.first << p.second << '\n';
    }

    return 0;
}

