// dp[i][j] = best second digit when considering subarray s[i..j]
// for Masha's turn (minimizing) or Petya's turn (maximizing)
// returns the pair of digits that will remain at the end
pair<int, int> dp[105][105];

// Function to simulate optimal play between Masha and Petya
pair<int, int> solve(int l, int r, bool isMashaTurn) {
    if (r - l + 1 == 2) {
        return {s[l] - '0', s[r] - '0'};
    }
    if (dp[l][r].first != -1) return dp[l][r];

    if (isMashaTurn) {
        // Masha wants to minimize the final result
        pair<int, int> res = {2, 2};
        for (int i = l; i <= r; ++i) {
            char val = s[i];
            vector<char> options;
            if (val == '?') {
                options.push_back('0');
                options.push_back('1');
            } else {
                options.push_back(val);
            }

            for (char c : options) {
                string new_s = s;
                new_s[i] = c;
                auto next = solve(l, r, false);
                pair<int, int> curr;
                if (i == l) {
                    curr = {c - '0', next.first};
                } else if (i == r) {
                    curr = {next.first, c - '0'};
                } else {
                    curr = next;
                }

                if (curr < res) {
                    res = curr;
                }
            }
        }
        return dp[l][r] = res;
    } else {
        // Petya wants to maximize the final result
        pair<int, int> res = {-1, -1};
        for (int i = l; i <= r; ++i) {
            char val = s[i];
            vector<char> options;
            if (val == '?') {
