pair<char, char> dfs(int l, int r, int turn, vector<vector<int>>& memo, string& cur) {
    if (r - l == 2) {
        return {cur[l], cur[r]};
    }
    if (memo[l][r] != -1) {
        return memo[l][r] == 0 ? make_pair('0', '0') : make_pair('1', '1');
    }

    pair<char, char> res;
