        res = {'1', '1'};
        for (int i = l; i <= r; ++i) {
            cur[i] = '0';
            auto tmp = dfs(l, r, (turn + 1) % 2, memo, cur);
            cur[i] = '1';
            auto tmp1 = dfs(l, r, (turn + 1) % 2, memo, cur);
            cur[i] = '?';
            tmp = min(tmp, tmp1);
            if (tmp < res) {
                res = tmp;
            }
        }
