// The state returns a pair (first_bit, second_bit) in binary.

vector<vector<vector<pair<int, int>>>> memo;

pair<int, int> solve(int l, int r, int turn) {
    if (r - l + 1 == 2) {
        return {s[l] - '0', s[r] - '0'};
    }
    if (memo[l][r][turn].first != -1)
        return memo[l][r][turn];

    vector<pair<int, int>> options;

    for (int i = l; i <= r; ++i) {
        char val = s[i];
        // Try all possibilities for '?'
        for (int bit : {0, 1}) {
            if (val != '?' && bit != val - '0') continue;

            auto left = (i > l) ? solve(l, i - 1, 1 - turn) : make_pair(-1, -1);
            auto right = (i < r) ? solve(i + 1, r, 1 - turn) : make_pair(-1, -1);

            pair<int, int> res;
            if (left.first != -1 && left.second != -1) {
                res = left;
            } else if (right.first != -1 && right.second != -1) {
                res = right;
            } else {
