    if (turn == 0) {
        // Masha's turn: minimize
        sort(options.begin(), options.end());
        memo[l][r][turn] = options[0];
    } else {
        // Petya's turn: maximize
        sort(options.begin(), options.end(), greater<pair<int, int>>());
        memo[l][r][turn] = options[0];
    }

    return memo[l][r][turn];
