int n;
string s;

// Game simulation for a given array of digits (0 or 1)
vector<int> simulate_game(const vector<int>& cards) {
    vector<int> remaining(cards);
    bool turn_masha = true;
    while (remaining.size() > 2) {
        if (turn_masha) {
            // Masha's turn: minimize the final number
            // So she removes the card that leads to the smallest possible result
            int best_pos = 0;
            for (int i = 1; i < remaining.size(); ++i) {
                vector<int> temp = remaining;
                temp.erase(temp.begin() + i);
                vector<int> outcome = simulate_game(temp);
                if (outcome[0] * 2 + outcome[1] < remaining[best_pos] * 2 + remaining[i]) {
                    best_pos = i;
                }
            }
            remaining.erase(remaining.begin() + best_pos);
        } else {
            // Petya's turn: maximize the final number
            // He removes the card that leads to the largest possible result
            int best_pos = 0;
            for (int i = 1; i < remaining.size(); ++i) {
                vector<int> temp = remaining;
                temp.erase(temp.begin() + i);
                vector<int> outcome = simulate_game(temp);
                if (outcome[0] * 2 + outcome[1] > remaining[best_pos] * 2 + remaining[i]) {
                    best_pos = i;
                }
            }
            remaining.erase(remaining.begin() + best_pos);
        }
        turn_masha = !turn_masha;
    }
    return remaining;
}

void dfs(int idx, vector<int>& current, set<pair<int, int>>& outcomes) {
    if (idx == n) {
        vector<int> game_result = simulate_game(current);
        outcomes.insert({game_result[0], game_result[1]});
        return;
    }

    if (s[idx] == '0') {
        current.push_back(0);
        dfs(idx + 1, current, outcomes);
        current.pop_back();
    } else if (s[idx] == '1') {
        current.push_back(1);
        dfs(idx + 1, current, outcomes);
        current.pop_back();
    } else {
        // Try both 0 and 1
        current.push_back(0);
        dfs(idx + 1, current, outcomes);
        current.pop_back();

        current.push_back(1);
        dfs(idx + 1, current, outcomes);
        current.pop_back();
    }
}

