#include <bits/stdc++.h>
using namespace std;

vector<vector<int>> dp;
string s;

int solve(int l, int r, int turn) {
    if (r - l + 1 == 2)
        return (s[l] - '0') * 2 + (s[r] - '0');

    if (dp[l][r] != -1)
        return dp[l][r];

    if (turn % 2 == 0) { // Masha's turn (minimizing)
        int res = INT_MAX;
        for (int i = l; i <= r; ++i) {
            int val = s[i] == '?' ? 0 : s[i] - '0';
            string temp_s = s;
            s.erase(i, 1);
            int min_val = solve(l, r - 1, turn + 1);
            s.insert(i, 1, temp_s[i]);
            if (val == 0) {
                min_val = solve(l, r - 1, turn + 1);
            } else {
                min_val = solve(l, r - 1, turn + 1);
            }
            res = min(res, min_val);
        }
        return dp[l][r] = res;
    } else { // Petya's turn (maximizing)
        int res = INT_MIN;
        for (int i = l; i <= r; ++i) {
            int val = s[i] == '?' ? 0 : s[i] - '0';
            string temp_s = s;
            s.erase(i, 1);
            int max_val = solve(l, r - 1, turn + 1);
            s.insert(i, 1, temp_s[i]);
            if (val == 0) {
                max_val = solve(l, r - 1, turn + 1);
            } else {
                max_val = solve(l, r - 1, turn + 1);
            }
            res = max(res, max_val);
        }
        return dp[l][r] = res;
    }
}

void dfs(int idx, vector<char>& curr, set<pair<char, char>>& outcomes) {
    if (idx == s.size()) {
        string temp = "";
        for (char c : curr)
            temp += c;
        s = temp;
        int result = solve(0, (int)s.size() - 1, 0);
        outcomes.insert({result / 2 + '0', result % 2 + '0'});
        return;
    }

    if (s[idx] == '?') {
        curr.push_back('0');
        dfs(idx + 1, curr, outcomes);
        curr.pop_back();

        curr.push_back('1');
        dfs(idx + 1, curr, outcomes);
        curr.pop_back();
    } else {
        curr.push_back(s[idx]);
        dfs(idx + 1, curr, outcomes);
        curr.pop_back();
    }
}

