bool is_punct(const string &t) {
    return t.size() == 1 && (t[0] == '.' || t[0] == ',' || t[0] == '!' || t[0] == '?');
}

int main() {
    string s;
    getline(cin, s);
    vector<string> tokens;
    int i = 0;
    int n = s.length();
    while (i < n) {
        while (i < n && s[i] == ' ') {
            i++;
        }
        if (i >= n) {
            break;
        }
        if (isalpha(s[i])) {
            int j = i;
            while (j < n && isalpha(s[j])) {
                j++;
            }
            tokens.push_back(s.substr(i, j - i));
            i = j;
        } else {
            tokens.push_back(s.substr(i, 1));
            i += 1;
        }
    }
    if (tokens.empty()) {
        return 0;
    }
    string result = tokens[0];
    for (size_t k = 1; k < tokens.size(); ++k) {
        string current = tokens[k];
        bool prev_is_word = !is_punct(tokens[k-1]);
        bool curr_is_word = !is_punct(current);
        if (curr_is_word) {
            result += " " + current;
        } else {
            result += current;
        }
    }
    cout << result << endl;
    return 0;
}

