using namespace std;

long long gcd(long long a, long long b) {
    while (b) {
        long long t = a % b;
        a = b;
        b = t;
    }
    return a;
}

long long extended_gcd(long long a, long long b, long long &x, long long &y) {
    if (b == 0) {
        x = 1;
        y = 0;
        return a;
    } else {
        long long x1, y1;
        long long g = extended_gcd(b, a % b, x1, y1);
        x = y1;
        y = x1 - (a / b) * y1;
        return g;
    }
}

long long mod_inverse(long long a, long long m) {
    long long x, y;
    long long g = extended_gcd(a, m, x, y);
    if (g != 1) {
        return -1;
    } else {
        return (x % m + m) % m;
    }
}

bool solve_congruence(int a, int m, int b, int k, long long &x0) {
    long long m1 = m;
    long long m2 = k;
    long long A = a;
    long long B_val = b;
    long long x, y;
    long long g = extended_gcd(m1, m2, x, y);
    if ((B_val - A) % g != 0) {
        return false;
    }
    long long c = (B_val - A) / g;
    long long m1_div = m1 / g;
    long long m2_div = m2 / g;
    long long inv = mod_inverse(m1_div, m2_div);
    if (inv == -1) {
        return false;
    }
    long long k0 = (c * inv) % m2_div;
    x0 = A + m1 * k0;
    long long lcm = (m1 / g) * m2;
    x0 = x0 % lcm;
    if (x0 < 0) {
        x0 += lcm;
    }
    return true;
}

long long compute_count(long long n, int a, int m, int b, int k) {
    long long x0;
    if (!solve_congruence(a, m, b, k, x0)) {
        return 0;
    }
    long long g = gcd(m, k);
    long long lcm_val = (m / g) * k;
    if (x0 > n - 1) {
        return 0;
    }
    long long max_x = n - 1;
    long long num = (max_x - x0) / lcm_val + 1;
    return num;
}

int main() {
    long long n;
    cin >> n;
    string A, B;
    cin >> A >> B;
    int m = A.size();
    int k = B.size();
    long long nikephoros_losses = 0, polycarpus_losses = 0;
    for (int i = 0; i < m; ++i) {
        for (int j = 0; j < k; ++j) {
            long long cnt = compute_count(n, i, m, j, k);
            if (cnt == 0) continue;
            char a = A[i];
