#include <bits/stdc++.h>

using namespace std;

struct Compare {
    bool operator()(const pair<int, long long>& a, const pair<int, long long>& b) const {
        return a.first > b.first;
    }
};

int main() {
    int n;
    cin >> n;
    vector<pair<int, long long>> figures(n);
    for (int i = 0; i < n; ++i) {
        cin >> figures[i].second >> figures[i].first;
    }
    int t;
    cin >> t;
    vector<long long> p(t);
    for (int i = 0; i < t; ++i) {
        cin >> p[i];
    }

    // Compute phase capacities
    vector<long long> phase_capacities;
    long long prev = 0;
    for (int i = 0; i < t; ++i) {
        long long current = p[i];
        phase_capacities.push_back(current - prev);
        prev = current;
    }

    // Create the priority queue
    priority_queue<pair<int, long long>, vector<pair<int, long long>>, Compare> pq;
    for (const auto& fig : figures) {
        if (fig.second > 0) {
            pq.push({fig.first, fig.second});
        }
    }

    long long total = 0;

    // Process each phase
    for (int phase = 0; phase < t; ++phase) {
        long long current_cap = phase_capacities[phase];
        long long remaining_cap = current_cap;
        int factor = phase + 1;
        while (remaining_cap > 0 && !pq.empty()) {
            auto current = pq.top();
            pq.pop();
            if (current.second == 0) continue;
            long long use = min(remaining_cap, current.second);
            total += (long long)current.first * use * factor;
            remaining_cap -= use;
            if (current.second - use > 0) {
                pq.push({current.first, current.second - use});
            }
        }
    }

    // Process remaining figures with factor t+1
    while (!pq.empty()) {
        auto current = pq.top();
        pq.pop();
        total += (long long)current.first * current.second * (t + 1);
    }

    cout << total << endl;

    return 0;
}

