using namespace std;

int main() {
    int n;
    cin >> n;
    vector<string> moves(n);
    for (int i = 0; i < n; ++i) {
        cin >> moves[i];
    }

    // dx and dy represent the range of possible total displacement after all steps
    // Initially, we are at (0, 0), so we need to find all possible starting points
    // such that there's a sequence of movements from start to (0, 0)
    // So we track the min and max x and y after each step

    int minX = 0, maxX = 0;
    int minY = 0, maxY = 0;

    for (const string& move : moves) {
        int newMinX = minX, newMaxX = maxX;
        int newMinY = minY, newMaxY = maxY;

        for (char c : move) {
            switch (c) {
                case 'U':
                    newMaxY += 1;
                    newMinY -= 0;
                    break;
                case 'D':
                    newMinY -= 1;
                    newMaxY += 0;
                    break;
                case 'R':
                    newMaxX += 1;
                    newMinX -= 0;
                    break;
                case 'L':
                    newMinX -= 1;
                    newMaxX += 0;
                    break;
            }
        }

        // Take the union of all possibilities
        minX = min(minX, newMinX);
        maxX = max(maxX, newMaxX);
        minY = min(minY, newMinY);
        maxY = max(maxY, newMaxY);
    }

    cout << (maxX - minX + 1) * (maxY - minY + 1) << endl;
    return 0;
}

