        cin >> movements[i];
    }
    reverse(movements.begin(), movements.end());

    unordered_set<pair<long long, long long>, HashPair> current_set;
    current_set.insert({0LL, 0LL});
    int current_k = 0;

    for (const string& mov : movements) {
        int required_parity = (current_k + 1) % 2;
        unordered_set<pair<long long, long long>, HashPair> next_set;
        for (const auto& p : current_set) {
            long long x = p.first;
            long long y = p.second;
            for (char d : mov) {
                long long new_x, new_y;
                if (d == 'U') {
                    new_x = x;
                    new_y = y - 1;
                } else if (d == 'L') {
                    new_x = x + 1;
                    new_y = y;
                } else if (d == 'D') {
                    new_x = x;
                    new_y = y + 1;
                } else if (d == 'R') {
                    new_x = x - 1;
                    new_y = y;
                } else {
                    continue;
                }
                long long sum_parity = (new_x + new_y) % 2;
                if (sum_parity == required_parity) {
                    next_set.insert({new_x, new_y});
                }
            }
        }
        current_set.swap(next_set);
        current_k++;
    }

    cout << current_set.size() << endl;
    return 0;
}

