const int MAXN = 4;
int d[MAXN][MAXN];

bool solve(int len, vector<string>& res) {
    for (int i = 0; i < 4; ++i) {
        string s(len, 'a');
        res[i] = s;
    }

    for (int i = 0; i < 4; ++i) {
        for (int j = i + 1; j < 4; ++j) {
            int need = d[i][j];
            for (int k = 0; k < len && need > 0; ++k) {
                if (res[i][k] != res[j][k]) continue;
                res[j][k] = (res[j][k] == 'a') ? 'b' : 'a';
                --need;
            }
            if (need > 0) return false;
        }
    }
    return true;
}

void check_all(int& min_len, vector<string>& best) {
    for (int len = 0; len <= 6 * 100000; ++len) {
        for (int a = 0; a <= len; ++a) {
            for (int b = 0; a + b <= len; ++b) {
                for (int c = 0; a + b + c <= len; ++c) {
