#include <bits/stdc++.h>
using namespace std;

typedef long long ll;

ll extended_gcd(ll a, ll b, ll &x, ll &y) {
    if (b == 0) {
        x = 1; y = 0;
        return a;
    }
    ll x1, y1;
    ll g = extended_gcd(b, a % b, x1, y1);
    x = y1;
    y = x1 - (a / b) * y1;
    return g;
}

ll solve_crt(ll a, ll m1, ll b, ll m2) {
    ll x, y;
    ll g = extended_gcd(m1, m2, x, y);
    if ((b - a) % g != 0) {
        return -1;
    }
    ll tmp = x * ((b - a) / g) % (m2 / g);
    ll res = a + tmp * m1;
    ll l = m1 / g * m2;
    res = (res % l + l) % l;
    if (res < 0) res += l;
    return res;
}

pair<ll, ll> fast_doubling(ll n, ll m) {
    if (n == 0) return {0, 1};
    auto p = fast_doubling(n >> 1, m);
    ll c = (p.first * (2 * p.second - p.first)) % m;
    ll d = (p.first * p.first + p.second * p.second) % m;
    if (n & 1) {
        return {d, (c + d) % m};
    } else {
        return {c, d};
    }
}

ll fast_doubling_mod(ll n, ll m) {
    return fast_doubling(n, m).first;
}

