#include <bits/stdc++.h>
using namespace std;

pair<long long, long long> fast_doubling(int n, long long mod) {
    if (n == 0) {
        return {0, 1};
    }
    int m = n / 2;
    auto [a, b] = fast_doubling(m, mod);
    long long c = a * (2 * b - a);
    c = (c % mod + mod) % mod;
    long long d = (a * a + b * b) % mod;
    if (n % 2 == 0) {
        return {c, d};
    } else {
        return {d, (c + d) % mod};
    }
}

int main() {
    long long f;
    cin >> f;
    long long m1 = 8192;
    long long m2 = 1220703125;
    long long f_mod_m1 = f % m1;
    long long f_mod_m2 = f % m2;

    vector<long long> fib_sequence;
    fib_sequence.push_back(0);
    fib_sequence.push_back(1);

