const ll MOD = 10000000000000LL; // 10^13

// Function to compute the Pisano period for a given modulo m
pair<ll, vector<ll>> findPisanoPeriod(ll m) {
    if (m == 1) {
        return {0, {0, 1}};
    }

    unordered_map<ll, pair<ll, ll>> seen;
    ll a = 0, b = 1;
    ll period = 0;

    while (true) {
        if (seen.find(a) != seen.end()) {
            pair<ll, ll> prev = seen[a];
            if (prev.first == b) {
                period = seen.size();
                break;
            }
        } else {
            seen[a] = {b, period};
        }

        ll next = (a + b) % m;
        a = b;
        b = next;
        period++;
    }

    // Reconstruct the sequence up to the period
    vector<ll> fibs(period);
    a = 0, b = 1;
    for (ll i = 0; i < period; ++i) {
        fibs[i] = a;
        ll next = (a + b) % m;
        a = b;
        b = next;
    }

    return {period, fibs};
}

int main() {
    ll f;
    cin >> f;

    auto [period, fibs] = findPisanoPeriod(MOD);

    for (ll i = 0; i < period; ++i) {
        if (fibs[i] == f) {
