#include <unordered_map>
#include <vector>

using namespace std;

typedef long long ll;
const ll MOD = 10000000000000LL; // 10^13

pair<ll, ll> compute_fibonacci(ll n) {
    if (n == 0) return {0, 1};
    auto [a, b] = compute_fibonacci(n >> 1);
    ll c = a * (2 * b - a);
    ll d = a * a + b * b;
    if (n & 1) return {d % MOD, (c + d) % MOD};
    else return {c % MOD, d % MOD};
}

ll find_position(ll f) {
    if (f == 0) return 0;
    if (f == 1) return 1;

    unordered_map<ll, vector<ll>> seen;
    ll a = 0, b = 1;
    for (ll i = 0; i < MOD * 2; ++i) {
        if (seen.find(a) != seen.end()) {
            for (auto pos : seen[a]) {
                if (b == compute_fibonacci(pos + 1).first) {
                    return pos;
                }
            }
            return -1;
        }
        seen[a].push_back(i);
        ll next = (a + b) % MOD;
        a = b;
        b = next;
        if (a == f && b == compute_fibonacci(1).first) {
            return i;
        }
    }
    return -1;
}

