long long countNumbersWithSameFirstAndLastDigit(long long x) {
    string s = to_string(x);
    int n = s.length();
    long long res = 0;

    for (int len = 1; len <= n; ++len) {
        if (len == 1) {
            res += 9;
        } else {
            res += 9 * 10LL;
            for (int i = 1; i < len - 1; ++i)
                res *= 10;
        }
    }

    // Now subtract the numbers that are greater than x
    s = to_string(x);
    n = s.length();

    for (int len = 1; len < n; ++len) {
        continue; // already counted and not to be subtracted
    }

    if (n > 1) {
        char first = s[0];
        char last = s.back();

        if (first < last)
            res -= 9;
        else if (first == last) {
            bool flag = true;
            for (int i = 1; i < n - 1; ++i)
                if (s[i] < '0') {
                    flag = false;
                    break;
                }
            if (flag)
                res -= 0;
            else
                res -= 1;
        } else
            res -= 10;
    }

    return res;
}

