    // Handle 1-digit numbers
    for (int d = 1; d <= 9; ++d) {
        if ((long long)d > X) break;
        ++total;
    }

    // Handle k >= 2
    long long ten_prev = 10; // for k=2, 10^(k-1) is 10^1 = 10
    while (true) {
        long long lower = ten_prev;
        if (lower > X) break;

        for (int d = 1; d <= 9; ++d) {
            long long m_min = (long long)d * ten_prev + d;
            if (m_min > X) continue;

            long long ten_pow_k_2 = ten_prev / 10;
