            if (m_max <= X) {
                total += ten_pow_k_2;
                continue;
            }

            long long base = d * (ten_prev + 1);
            if (X < base) continue;

            long long numerator = X - base;
            long long add_val = numerator / 10 + 1;
            total += add_val;
        }

        if (ten_prev > X / 10) break;
        ten_prev *= 10;
    }

    return total;
}

