#include <iostream>

using namespace std;

long long mod_pow(long long base, long long exp, long long mod) {
    long long result = 1;
    base %= mod;
    while (exp > 0) {
        if (exp & 1)
            result = (result * base) % mod;
        base = (base * base) % mod;
        exp >>= 1;
    }
    return result;
}

int main() {
    long long n, m;
    cin >> n >> m;

    // Total moves required is (3^n - 1) / 2
    // We need to compute this modulo m

    if (m == 1) {
        cout << 0 << endl;
        return 0;
    }

    // Compute 3^n mod (2*m)
    long long power_mod = mod_pow(3, n, 2 * m);

    // Compute (power_mod - 1) / 2 mod m
    long long numerator = (power_mod - 1) % (2 * m);
    long long result = (numerator / 2) % m;

    cout << result << endl;
    return 0;
}

