    int n;
    cin >> n;
    vector<vector<int>> adj(n+1);
    for (int i = 0; i < n-1; ++i) {
        int a, b;
        cin >> a >> b;
        adj[a].push_back(b);
        adj[b].push_back(a);
    }

    vector<vector<double>> dp(n+1, vector<double>(n+1, -INF));
    function<void(int, int)> dfs = [&](int u, int parent) {
        dp[u][1] = 0.0;
        for (int v : adj[u]) {
            if (v == parent) continue;
            dfs(v, u);
            vector<double> temp(n+1, -INF);
            for (int s_prev = 1; s_prev <= n; ++s_prev) {
                if (dp[u][s_prev] < -1e15) continue;
                for (int s_child = 1; s_child <= n; ++s_child) {
                    if (dp[v][s_child] < -1e15) continue;
                    // Option 1: cut
                    double log_cut = dp[u][s_prev] + dp[v][s_child];
                    if (log_cut > temp[s_prev]) {
                        temp[s_prev] = log_cut;
                    }
                    // Option 2: not cut
                    double new_size = s_prev + s_child;
                    if (new_size > n) continue;
                    double log_not_cut = dp[u][s_prev] + dp[v][s_child] + log(new_size) - log(s_prev) - log(s_child);
                    if (log_not_cut > temp[new_size]) {
                        temp[new_size] = log_not_cut;
                    }
                }
            }
            for (int s = 1; s <= n; ++s) {
                dp[u][s] = temp[s];
            }
        }
    };

    dfs(1, -1);

    double max_log = -INF;
    for (int s = 1; s <= n; ++s) {
        if (dp[1][s] > max_log) {
            max_log = dp[1][s];
        }
    }

    long long result = llround(exp(max_log));
    cout << result << endl;
    return 0;
}

