vector<int> adj[MAXN];

void dfs(int u, int parent) {
    dp[u][1] = 1; // base case: the node itself is a component of size 1

    for (int v : adj[u]) {
        if (v == parent)
            continue;
        dfs(v, u);

        for (int i = 0; i <= u; ++i) {
            for (int j = 0; j <= v; ++j) {
                dp[u + j][i + j] = max(dp[u + j][i + j], dp[u][i] * dp[v][j]);
            }
        }

        // merge v's subtree into u's
        for (int sz = u + 1; sz >= 0; --sz) {
            for (int k = 1; k <= v; ++k) {
                if (dp[u][sz])
                    dp[sz + k][sz + k] = max(dp[sz + k][sz + k], dp[u][sz] * dp[v][k]);
            }
        }

        // combine results from previous combinations
        for (int sz = u + v; sz >= 0; --sz) {
            for (int k = 0; k < sz; ++k) {
