using namespace std;

const long long MAX_SIEVE = 1000000;
bool is_prime[MAX_SIEVE + 1];

void sieve() {
    memset(is_prime, true, sizeof(is_prime));
    is_prime[0] = is_prime[1] = false;
    for (long long i = 2; i * i <= MAX_SIEVE; ++i) {
        if (is_prime[i]) {
            for (long long j = i * i; j <= MAX_SIEVE; j += i) {
                is_prime[j] = false;
            }
        }
    }
}

bool is_perfect_square(long long x, long long &s) {
    long long low = 1, high = MAX_SIEVE;
    while (low <= high) {
        long long mid = (low + high) / 2;
        long long square = mid * mid;
        if (square == x) {
            s = mid;
            return true;
        } else if (square < x) {
            low = mid + 1;
        } else {
            high = mid - 1;
        }
    }
    return false;
}

int main() {
    sieve();
    long long n;
    cin >> n;
    vector<long long> x(n);
    for (long long i = 0; i < n; ++i) {
        cin >> x[i];
    }
    for (long long i = 0; i < n; ++i) {
        long long current = x[i];
        long long s;
        if (is_perfect_square(current, s)) {
            if (is_prime[s]) {
                cout << "YES" << endl;
            } else {
                cout << "NO" << endl;
            }
        } else {
            cout << "NO" << endl;
        }
    }
    return 0;
}

