            for (int i = 0; i < n; ++i) {
                adj[new_node][i] = 1;
                adj[i][new_node] = 1;
            }
            // The number of new triangles added is C(n, 2) = n*(n-1)/2
            int added_cycles = n * (n - 1) / 2;
            if (added_cycles > k) {
