        if (available >= 3) {
            // try to add a clique
            int m = 0;
            for (m = available; m >= 3; m--) {
                long long temp = (long long)m * (m-1) * (m-2);
                if (temp <= 6LL * k) break;
            }
            if (m >= 3) {
                // add clique
                int start = current_node;
                for (int i = start; i < start + m; i++) {
                    for (int j = i + 1; j < start + m; j++) {
                        matrix[i][j] = '1';
                        matrix[j][i] = '1';
                    }
                }
                cliques.push_back({start, m});
                current_node += m;
                k -= m * (m-1) * (m-2) / 6;
                // now process adding nodes connected to this clique
                while (true) {
                    available = MAXN - current_node;
                    if (available == 0) break;
                    int latest_start = cliques.back().first;
                    int latest_size = cliques.back().second;
                    int t;
                    for (t = latest_size; t >= 2; t--) {
                        if ((long long)t * (t-1) / 2 <= k) break;
                    }
                    if (t < 2) break;
                    // add node connected to first t nodes in latest clique
                    for (int i = latest_start; i < latest_start + t; i++) {
                        matrix[current_node][i] = '1';
                        matrix[i][current_node] = '1';
                    }
                    current_node++;
                    k -= t * (t-1) / 2;
                }
            } else {
