vector<int> decompose(int k) {
    vector<int> cliques;
    while (k > 0) {
        int m = 2;
        while (true) {
            long long val = (long long)m * (m - 1) * (m - 2);
            if (val > 6LL * k) break;
            ++m;
        }
        --m;
        cliques.push_back(m);
        long long contrib = (long long)m * (m - 1LL) * (m - 2LL) / 6LL;
        k -= contrib;
    }
    return cliques;
}

