            for (int i = 0; i < n; ++i) {
                graph[n][i] = 1;
                graph[i][n] = 1;
            }
            k -= new_cycles;
            ++n;
        } else {
            // Connect only enough to add k cycles
            int needed = k;
            for (int i = 0; i < n && needed > 0; ++i) {
                for (int j = i + 1; j < n && needed > 0; ++j) {
                    graph[n][i] = 1;
                    graph[i][n] = 1;
                    graph[n][j] = 1;
                    graph[j][n] = 1;
                    --needed;
                }
            }
            k = 0;
            ++n;
            break;
        }
        if (k == 0) break;
    }

    cout << n << endl;
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            cout << graph[i][j];
        }
        cout << endl;
    }

    return 0;
}

