#include <queue>
#include <utility>

using namespace std;

int main() {
    int m, k;
    cin >> m >> k;
    vector<int> d(m), s(m);
    for (int i = 0; i < m; ++i) cin >> d[i];
    for (int i = 0; i < m; ++i) cin >> s[i];

    long long time = 0;
    long long fuel = 0;
    priority_queue<pair<int, int>, vector<pair<int, int>>, greater<>> supply_heap;

    for (int i = 0; i < m; ++i) {
        // Add current city's fuel supply to the heap with its earliest available time
        if (i == 0) {
            // At initial time 0, get first supply
            supply_heap.push({0, s[i]});
        } else {
            supply_heap.push({time + k, s[i]});
        }

        // While we don't have enough fuel to go to next city
        while (fuel < d[i]) {
            if (supply_heap.empty()) {
                // This should never happen as per problem constraints
                break;
            }
            auto [available_time, fuel_amount] = supply_heap.top();
            supply_heap.pop();

            // Wait until this fuel is available
            if (available_time > time) {
                time = available_time;
            }

            // Take as much fuel as needed
            int take = min(fuel_amount, static_cast<int>(d[i] - fuel));
            fuel += take;
            time += take;
        }

        // After using some fuel to reach next city
        fuel -= d[i];
    }

    cout << time << endl;
    return 0;
}

