#include <bits/stdc++.h>

using namespace std;

int main() {
    int n;
    long long d;
    cin >> n >> d;
    vector<long long> x(n);
    for (int i = 0; i < n; ++i) cin >> x[i];
    long long total = 0;
    for (int i = 0; i < n; ++i) {
        int low = i;
        int high = n - 1;
        int best = i;
        while (low <= high) {
            int mid = (low + high) / 2;
            if (x[mid] - x[i] <= d) {
                best = mid;
                low = mid + 1;
            } else {
                high = mid - 1;
            }
        }
        int m = best - i;
        if (m >= 2) {
            total += (long long)m * (m - 1) / 2;
        }
    }
    cout << total << endl;
    return 0;
}

