// Apply permutation q to p: p becomes p[q[0]], p[q[1]], ..., p[q[n-1]]
vector<int> applyPermutation(const vector<int>& p, const vector<int>& q) {
    vector<int> res(p.size());
    for (size_t i = 0; i < q.size(); ++i)
        res[i] = p[q[i] - 1];
    return res;
}

// Apply inverse of permutation q to p
vector<int> applyInversePermutation(const vector<int>& p, const vector<int>& q) {
    vector<int> res(p.size());
    for (size_t i = 0; i < q.size(); ++i)
        res[q[i] - 1] = p[i];
    return res;
}

bool canReach(vector<int> initial, vector<int> target, vector<int> q, int k, unordered_set<string>& seen, string path = "") {
    if (k == 0) {
        return initial == target;
    }

    string state = "";
    for (int x : initial) state += to_string(x);
    if (seen.count(state)) return false;
    seen.insert(state);

    // Try applying permutation q (option 1)
    vector<int> next1 = applyPermutation(initial, q);
    if (canReach(next1, target, q, k - 1, seen, path + "1"))
        return true;

    // Try applying inverse of permutation q (option 2)
    vector<int> next2 = applyInversePermutation(initial, q);
    if (canReach(next2, target, q, k - 1, seen, path + "2"))
        return true;

    return false;
}

int main() {
    int n, k;
    cin >> n >> k;

    vector<int> q(n);
    for (int i = 0; i < n; ++i)
        cin >> q[i];

    vector<int> s(n);
    for (int i = 0; i < n; ++i)
        cin >> s[i];

    // Initial permutation is [1, 2, ..., n]
    vector<int> initial(n);
    for (int i = 0; i < n; ++i)
        initial[i] = i + 1;

    unordered_set<string> seen;
    bool result = canReach(initial, s, q, k, seen);

    cout << (result ? "YES" : "NO") << endl;
    return 0;
}

