bool isPossible(int n, int k, const vector<int>& q, const vector<int>& s) {
    vector<int> initial(n);
    for (int i = 0; i < n; ++i)
        initial[i] = i + 1;

    // BFS approach
    unordered_set<string> visited;
    vector<pair<vector<int>, int>> queue; // {permutation, steps}
    queue.push_back({initial, 0});
