    if (i >= n || j + 1 >= m || grid[i][j] != '.' || grid[i][j+1] != '.')
        return false;
    grid[i][j] = ch;
    grid[i][j+1] = ch;
    used_a++;
    return true;
}

bool place_vertical(int i, int j, char ch) {
    if (i + 1 >= n || j >= m || grid[i][j] != '.' || grid[i+1][j] != '.')
        return false;
    grid[i][j] = ch;
    grid[i+1][j] = ch;
    used_b++;
    return true;
}

bool place_square(int i, int j, char ch) {
    if (i + 1 >= n || j + 1 >= m || grid[i][j] != '.' || grid[i][j+1] != '.' || grid[i+1][j] != '.' || grid[i+1][j+1] != '.')
        return false;
    grid[i][j] = ch;
    grid[i][j+1] = ch;
    grid[i+1][j] = ch;
    grid[i+1][j+1] = ch;
    used_c++;
    return true;
}

bool solve() {
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < m; ++j)
            grid[i][j] = '.';

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < m; ++j) {
            if (grid[i][j] != '.') continue;

            if (a > 0 && j + 1 < m && grid[i][j+1] == '.') {
                if (place_horizontal(i, j, 'a' + (used_a % 26))) {
                    a--;
                    j++;
                }
            } else if (b > 0 && i + 1 < n && grid[i+1][j] == '.') {
                if (place_vertical(i, j, 'a' + (used_b % 26))) {
                    b--;
                    i++;
                    continue;
                }
            } else if (c > 0 && i + 1 < n && j + 1 < m) {
                if (place_square(i, j, 'a' + (used_c % 26))) {
                    c--;
                    i += 1;
                    j += 1;
                    continue;
                }
            } else {
                // Try to cover with remaining horizontal or vertical planks from other positions
                bool placed = false;
                if (a > 0 && j + 1 < m) {
                    if (place_horizontal(i, j, 'a' + (used_a % 26))) {
                        a--;
                        placed = true;
                        j++;
