using namespace std;

const int MAX = 200010;
long double dp[2][MAX];

int main() {
    int n, m, k;
    cin >> n >> m >> k;

    if (m > 0 && n == 0 && k == 0) {
        cout << fixed << setprecision(6) << 0.0 << endl;
        return 0;
    }

    long double total = 1.0;
    for (int i = 1; i <= n + m; ++i) {
        total *= i;
    }

    int cur = 0;
    dp[cur][0] = 1.0;

    for (int i = 0; i < n + m; ++i) {
        int next = 1 - cur;
        fill(dp[next], dp[next] + MAX, 0.0);

        int a = min(i, n);
        for (int j = max(0, -k); j <= min(k + n, a); ++j) {
            if (dp[cur][j + MAX / 2 + k] == 0) continue;

            // Person with 10 euro
            if (a > 0) {
                dp[next][j + 1 + MAX / 2 + k] += dp[cur][j + MAX / 2 + k];
            }

            // Person with 20 euro
            if (m > 0 && j >= 0) {
                dp[next][j - 1 + MAX / 2 + k] += dp[cur][j + MAX / 2 + k];
            }
        }

        cur = next;
    }

    long double valid = 0.0;
    for (int j = 0; j <= MAX; ++j) {
        valid += dp[cur][j];
    }

    cout << fixed << setprecision(6) << valid / total << endl;
    return 0;
}

