#include <iostream>
#include <iomanip>
#include <vector>

using namespace std;

const int MAX = 200010;
long long fact[MAX];
long long invfact[MAX];
long long mod = 1000000007;

long long power(long long a, long long b) {
    long long res = 1;
    while (b > 0) {
        if (b & 1) res = res * a % mod;
        a = a * a % mod;
        b >>= 1;
    }
    return res;
}

void precompute() {
    fact[0] = 1;
    for (int i = 1; i < MAX; ++i) {
        fact[i] = fact[i - 1] * i % mod;
    }
    invfact[MAX - 1] = power(fact[MAX - 1], mod - 2);
    for (int i = MAX - 2; i >= 0; --i) {
        invfact[i] = invfact[i + 1] * (i + 1) % mod;
    }
}

long long comb(int n, int k) {
    if (k < 0 || k > n) return 0;
    return fact[n] * invfact[k] % mod * invfact[n - k] % mod;
}

double solve(int n, int m, int k) {
    if (m == 0) return 1.0;
    if (n == 0 && m > 0) return 0.0;

    double total = 0.0;
    for (int i = 0; i <= min(m, n + k); ++i) {
        int needed_10s = max(0, m - i);
        if (needed_10s > k) continue;

        long long ways = 0;
        ways = comb(n + m, i);
        ways *= comb(n + m - i, m - i);
        ways %= mod;

        total += static_cast<double>(ways) / comb(n + m, m);
    }

    return total;
}

int main() {
    precompute();
    int n, m, k;
    cin >> n >> m >> k;

    double result = solve(n, m, k);

    cout << fixed << setprecision(10) << result << endl;
    return 0;
}

