using namespace std;

const int MAX = 200010;
long double dp[2][MAX];

int main() {
    int n, m, k;
    cin >> n >> m >> k;

    if (n < m || n < 0 || m < 0) {
        cout << fixed << setprecision(6) << 0.0 << endl;
        return 0;
    }

    if (m == 0) {
        cout << fixed << setprecision(6) << 1.0 << endl;
        return 0;
    }

    if (k + n < m) {
        cout << fixed << setprecision(6) << 0.0 << endl;
        return 0;
    }

    int total = n + m;
    int max_ten = min(n, k + n - m);
    for (int i = 0; i <= max_ten; ++i)
        dp[0][i] = 1.0;

    for (int i = 1; i <= total; ++i) {
        int cur = i % 2;
        int prev = 1 - cur;
        fill(dp[cur], dp[cur] + MAX, 0);

        for (int ten = 0; ten <= max_ten; ++ten) {
            if (dp[prev][ten] == 0) continue;

            int people_left = total - i;
            long double prob_10 = (double)(n - (i - ten)) / people_left;
            long double prob_20 = (double)(m - (i - ten)) / people_left;

            if (i - ten < n && ten < max_ten) {
                dp[cur][ten + 1] += dp[prev][ten] * prob_10;
            }

            if (i - ten < m && ten > 0) {
                dp[cur][ten - 1] += dp[prev][ten] * prob_20;
            }
        }
    }

    long double res = 0;
    for (int ten = 0; ten <= max_ten; ++ten)
        res += dp[total % 2][ten];

    long double all_ways = 1.0;
    for (int i = 1; i <= n + m; ++i)
        all_ways *= (n + m - i + 1) / (double)i;

    cout << fixed << setprecision(10) << res / all_ways << endl;

    return 0;
}

