#include <bits/stdc++.h>
using namespace std;

int main() {
    int m;
    cin >> m;
    vector<int> q_list(m);
    for (int i = 0; i < m; ++i) {
        cin >> q_list[i];
    }
    int n;
    cin >> n;
    vector<long long> a(n);
    for (int i = 0; i < n; ++i) {
        cin >> a[i];
    }
    // Sort in non-increasing order
    sort(a.begin(), a.end(), greater<long long>());
    long long total_sum = 0;
    for (int i = 0; i < n; ++i) {
        total_sum += a[i];
    }
    // Compute suffix sum
    vector<long long> suffix_sum(n + 1, 0);
    for (int i = 1; i <= n; ++i) {
        suffix_sum[i] = suffix_sum[i-1] + a[n - i];
    }
    long long min_cost = total_sum; // Initialize with no discount case
    for (int q : q_list) {
        int q_plus_2 = q + 2;
        int full_groups = n / q_plus_2;
        int remaining = n % q_plus_2;
        long long free_from_full = (long long) full_groups * 2;
        if (remaining > q) {
            long long add = min(2LL, (long long)(remaining - q));
            free_from_full += add;
        }
        long long x = free_from_full;
        x = min(x, (long long)n);
        long long current_cost = total_sum - suffix_sum[x];
        if (current_cost < min_cost) {
            min_cost = current_cost;
        }
    }
    cout << min_cost << endl;
    return 0;
}

