#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

int main() {
    int n, m;
    cin >> n >> m;

    vector<int> species(n);
    for (int i = 0; i < n; ++i) {
        cin >> species[i];
        string dummy;
        cin >> dummy; // Read and ignore the position as it's not needed for this approach
    }

    // We will use a DP approach to find the longest non-decreasing subsequence
    // where the sequence must be 1, 2, ..., m in order.
    vector<int> dp(m + 1, 0); // dp[k] is the length of the LIS ending with species k

    for (int s : species) {
        // Find the largest index j such that dp[j] is <= dp[s-1]
        // This can be optimized using binary search
        int len = 0;
        for (int j = 1; j < s; ++j) {
            if (dp[j] > len) {
                len = dp[j];
            }
        }
        dp[s] = max(dp[s], len + 1);
    }

    int max_len = 0;
    for (int i = 1; i <= m; ++i) {
        max_len = max(max_len, dp[i]);
    }

    cout << n - max_len << endl;
    return 0;
}

