void factorize(int n, vector<int>& exponents, int idx, vector<int>& currentExponents, vector<ll>& result) {
    if (n == 1) {
        result.push_back(1);
        return;
    }
    if (idx >= primes.size()) return;

    int prime = primes[idx];
    int maxExp = 0;
    while (n % prime == 0) {
        n /= prime;
        ++maxExp;
    }

    for (int e = 0; e <= maxExp; ++e) {
        if (e > 0) {
            if (!currentExponents.empty() && currentExponents.back() < e) continue;
        }
        if (e > 0) currentExponents.push_back(e);
        factorize(n, exponents, idx + 1, currentExponents, result);
        if (e > 0) currentExponents.pop_back();
    }
}

