    int to, rev, capacity;
    Edge(int t, int r, int c) : to(t), rev(r), capacity(c) {}
};

vector<Edge> graph[MAXN];
int level[MAXN], ptr[MAXN];

void add_edge(int u, int v, int cap) {
    graph[u].push_back(Edge(v, (int)graph[v].size(), cap));
    graph[v].push_back(Edge(u, (int)graph[u].size() - 1, 0));
}

bool bfs(int s, int t) {
    fill(level, level + MAXN, -1);
    queue<int> q;
    level[s] = 0;
    q.push(s);
    while (!q.empty()) {
        int u = q.front(); q.pop();
        for (auto& e : graph[u]) {
            if (e.capacity > 0 && level[e.to] == -1) {
                level[e.to] = level[u] + 1;
                q.push(e.to);
            }
        }
    }
    return level[t] != -1;
}

int dfs(int u, int t, int flow) {
    if (u == t)
        return flow;
    for (; ptr[u] < (int)graph[u].size(); ++ptr[u]) {
        Edge& e = graph[u][ptr[u]];
        if (e.capacity > 0 && level[e.to] == level[u] + 1) {
            int min_flow = dfs(e.to, t, min(flow, e.capacity));
            if (min_flow > 0) {
                e.capacity -= min_flow;
                graph[e.to][e.rev].capacity += min_flow;
                return min_flow;
            }
        }
    }
    return 0;
}

