        int v = q.front(); q.pop();
        for (auto e : G[v]) {
            if (level[e.to] < 0 && e.to != s)
                level[e.to] = level[v] + 1, q.push(e.to);
        }
    }
    return level[t] >= 0;
}

int dfs(int v, int t, int f) {
