    vector<vector<int>> graph(n);

    for (int i = 0; i < n; ++i) {
        int d = fav[i];
        if (i + d < n) {
            graph[i].push_back(i + d);
            graph[i + d].push_back(i);
        }
        if (i - d >= 0) {
            graph[i].push_back(i - d);
            graph[i - d].push_back(i);
        }
    }

    for (int i = 0; i < n; ++i) {
        if (visited[i]) continue;
        queue<int> q;
        q.push(i);
        visited[i] = true;
        while (!q.empty()) {
            int u = q.front();
            q.pop();
            for (int v : graph[u]) {
                if (!visited[v]) {
                    visited[v] = true;
                    q.push(v);
                }
            }
        }
    }

    vector<bool> pos1(n + 1), pos2(n + 1);
    for (int i = 0; i < n; ++i) {
        pos1[i + 1] = visited[i];
        pos2[target[i]] = visited[i];
    }

    return pos1 == pos2;
}

int main() {
    int n;
    cin >> n;
    vector<int> permutation(n);
    for (int i = 0; i < n; ++i)
        cin >> permutation[i];
    vector<int> favorite(n);
    for (int i = 0; i < n; ++i)
        cin >> favorite[i];

    if (canReachState(n, permutation, favorite))
        cout << "YES" << endl;
    else
        cout << "NO" << endl;

    return 0;
}

