    vector<pair<int, int>> eggs(n);
    for (int i = 0; i < n; ++i) {
        cin >> eggs[i].first >> eggs[i].second;
    }

    long long totalA = 0, totalG = 0;
    vector<char> result(n);

    // Try to assign each egg greedily to minimize the difference
    for (int i = 0; i < n; ++i) {
        if (eggs[i].first > eggs[i].second) {
            result[i] = 'A';
            totalA += eggs[i].first;
        } else {
            result[i] = 'G';
            totalG += eggs[i].second;
        }
    }

    long long diff = abs(totalA - totalG);

    if (diff <= 500) {
        for (char c : result) {
            cout << c;
        }
        cout << endl;
    } else {
        // Try to fix the imbalance by flipping some choices
        bool found = false;
        for (int i = 0; i < n && !found; ++i) {
            int a = eggs[i].first;
