    vector<long long> total;

    prefix.push_back(0);
    length.push_back(1);
    total.push_back(0);

    for (int i = 0; i < n; ++i) {
        int type;
        cin >> type;

        if (type == 1) {
            int a, x;
            cin >> a >> x;
            // Add x to the first a elements
            prefix[0] += (long long)a * x;
            total[0] += (long long)a * x;
        } else if (type == 2) {
            int k;
            cin >> k;
            // Append k to the end
            long long new_prefix = prefix.back() + k;
            long long new_total = total.back() + k;
            prefix.push_back(new_prefix);
            length.push_back(length.back() + 1);
            total.push_back(new_total);
        } else {
            // Remove last element
            prefix.pop_back();
            length.pop_back();
            total.pop_back();
        }

        double avg = (double)total.back() / length.back();
        cout << fixed << setprecision(6) << avg << "\n";
    }

    return 0;
}

