    vector<int> lengths;
    stack<pair<int, long long>> addStack; // (count, total)

    long long sum = 0;
    int size = 1;

    prefixSum.push_back(0);
    lengths.push_back(1);

    for (int i = 0; i < n; ++i) {
        int type;
        cin >> type;

        if (type == 1) {
            int a, x;
            cin >> a >> x;
            sum += (long long)a * x;
            addStack.push({a, (long long)x});
        } else if (type == 2) {
            int k;
            cin >> k;
            sum = sum + k;
            size++;
            prefixSum.push_back(sum);
            lengths.push_back(size);
        } else {
            sum -= prefixSum.back();
            size--;
            if (!addStack.empty()) {
                auto [cnt, val] = addStack.top();
                sum -= (long long)cnt * val;
                addStack.pop();
            }
            prefixSum.pop_back();
            lengths.pop_back();
        }

        double avg = (double)sum / size;
        cout << fixed << setprecision(6) << avg << '\n';
    }

    return 0;
