bool isPrimitiveRoot(long long x, long long p) {
    vector<long long> factors;
    long long phi = p - 1;

    // Find all the distinct prime factors of phi
    for (long long i = 2; i * i <= phi; ++i) {
        if (phi % i == 0) {
            factors.push_back(i);
            while (phi % i == 0)
                phi /= i;
        }
    }
    if (phi > 1)
        factors.push_back(phi);

    // Check for each factor if x^((p-1)/f) mod p == 1
    for (long long f : factors) {
        long long power = (p - 1) / f;
        long long result = 1;
        long long base = x % p;
        while (power > 0) {
            if (power % 2 == 1)
                result = (result * base) % p;
            base = (base * base) % p;
            power /= 2;
        }
        if (result == 1)
            return false;
    }

    return true;
}

int main() {
    long long p;
    cin >> p;

    int count = 0;
    for (long long x = 2; x < p; ++x) {
        if (isPrimitiveRoot(x, p))
            ++count;
    }

