    for (int i = 1; i < n; ++i) {
        if (result[i] == result[i - 1]) {
            for (char c = 'a'; c <= 'z'; ++c) {
                if (c != result[i - 1] && c != result[i + 1]) {
                    result[i] = c;
                    break;
                }
            }
        }
    }

    cout << result << endl;
    return 0;
}

