    for (int i = 0; i < n; ++i) {
        if (s[i] == 'R') {
            s_start = i + 1;
            break;
        }
    }

    // Find the last 'L' from right to left
    for (int i = n - 1; i >= 0; --i) {
        if (s[i] == 'L') {
            t_end = i;
            break;
        }
    }

    // If no 'R' found, then start is before the first 'L'
    if (s_start == -1) {
        for (int i = n - 1; i >= 0; --i) {
            if (s[i] == 'L') {
                s_start = i;
                break;
