    int n = s.length();
    vector<int> dp(n + 1);
    dp[0] = 1; // empty prefix is valid

    for (int i = 1; i <= n; ++i) {
        for (int j = 0; j < i; ++j) {
            string sub = s.substr(j, i - j);
            if (isValidEmail(sub) && dp[j]) {
                dp[i] = 1;
                break;
            }
        }
    }

    if (!dp[n]) return false;

    int pos = n;
    while (pos > 0) {
        for (int j = 0; j < pos; ++j) {
            string sub = s.substr(j, pos - j);
            if (isValidEmail(sub) && dp[j]) {
                result.push_back(sub);
                pos = j;
                break;
            }
        }
    }

    reverse(result.begin(), result.end());
    return true;
}

