    int n = s.size();
    vector<int> positions;
    for (int i = 0; i < n; ++i) {
        if (s[i] == '@') positions.push_back(i);
    }

    // Try all possible ways to split the string into valid emails
    // Each email must contain exactly one '@'
    // So we need to find a way to partition the string using the '@' positions
    // such that each part is a valid email

    vector<string> result;
    int prev = -1;
    for (int i = 0; i < positions.size(); ++i) {
        if (positions[i] - prev > 1 && i + 1 == positions.size() || i + 1 < positions.size() && positions[i + 1] - positions[i] > 1) {
            if (prev == -1) {
                if (positions[i] == 0) continue;
                prev = 0;
            } else {
                if (positions[i] - prev <= 1) continue;
                prev = positions[i];
            }
        } else {
            continue;
        }
    }

    prev = -1;
    for (int i = 0; i < positions.size(); ++i) {
        if (prev == -1) {
            if (positions[i] == 0) continue;
            prev = 0;
        } else {
            if (positions[i] - prev <= 1) continue;
        }
        string candidate = s.substr(prev, positions[i] - prev);
        if (!isValidEmail(candidate)) continue;
        result.push_back(candidate);
        prev = positions[i];
    }

    if (prev != -1 && prev < n - 1) {
        string lastPart = s.substr(prev);
        if (isValidEmail(lastPart)) {
            result.push_back(lastPart);
        } else {
            return "No solution";
        }
    }

