using namespace std;

vector<vector<int>> grid;
int n, m;
vector<pair<int, int>> path;
vector<pair<pair<int, int>, pair<int, int>>> teleporters;

bool is_valid(int x, int y) {
    return x >= 1 && x <= n && y >= 1 && y <= m;
}

void dfs(int x, int y) {
    path.push_back({x, y});
    if (path.size() == n * m)
        return;

    // Try to move in all four directions
    vector<pair<int, int>> directions = {{0, 1}, {1, 0}, {0, -1}, {-1, 0}};
    for (auto [dx, dy] : directions) {
        int nx = x + dx, ny = y + dy;
        if (is_valid(nx, ny) && find(path.begin(), path.end(), make_pair(nx, ny)) == path.end()) {
            dfs(nx, ny);
            if (path.size() == n * m)
                return;
            path.pop_back();
        }
    }

    // If no valid move, add a teleporter
    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j <= m; ++j) {
            if (make_pair(i, j) != make_pair(x, y) && find(path.begin(), path.end(), make_pair(i, j)) == path.end()) {
                teleporters.push_back({{x, y}, {i, j}});
                dfs(i, j);
                if (path.size() == n * m)
                    return;
                path.pop_back();
                teleporters.pop_back();
            }
        }
    }
}

