    Crossword() {
        for (int i = 0; i < H; ++i)
            for (int j = 0; j < W; ++j)
                grid[i][j] = '.';
    }

    void place(string v1, string h1, string h2, string v2) {
        // Top-left vertical: v1
        for (int i = 0; i < 3; ++i)
            grid[i][0] = v1[i];
        // Bottom-right vertical: v2
        for (int i = 3; i < 6; ++i)
            grid[i][5] = v2[i - 3];
        // Top horizontal: h1
        for (int j = 0; j < 3; ++j)
            grid[0][j + 3] = h1[j];
        // Bottom horizontal: h2
        for (int j = 3; j < 6; ++j)
            grid[5][j - 3] = h2[j - 3];

        // Middle vertical: from v1[2] to v2[0]
        for (int i = 1; i < 5; ++i)
            if (grid[i][2] == '.') grid[i][2] = 'X';
        // Middle horizontal: from h1[2] to h2[2]
        for (int j = 1; j < 5; ++j)
            if (grid[2][j] == '.') grid[2][j] = 'X';
    }

    string toString() const {
        string res;
        for (int i = 0; i < H; ++i) {
            for (int j = 0; j < W; ++j)
                res += grid[i][j] == 'X' ? '.' : grid[i][j];
