using namespace std;

int main() {
    int n, m;
    cin >> n >> m;

    vector<vector<int>> grid(n, vector<int>(m));
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < m; ++j) {
            cin >> grid[i][j];
        }
    }

    int a, b;
    cin >> a >> b;

    int min_trees = 1000000;

    // Try both orientations: a x b and b x a
    for (int width : {a, b}) {
        for (int height : {b, a}) {
            if (width > m || height > n) continue;

            // Precompute prefix sums
            vector<vector<int>> prefix(n + 1, vector<int>(m + 1, 0));
            for (int i = 1; i <= n; ++i) {
                for (int j = 1; j <= m; ++j) {
                    prefix[i][j] = grid[i - 1][j - 1] + prefix[i - 1][j] + prefix[i][j - 1] - prefix[i - 1][j - 1];
                }
            }

            for (int i = 0; i <= n - height; ++i) {
                for (int j = 0; j <= m - width; ++j) {
                    int total = prefix[i + height][j + width] 
                              - prefix[i][j + width] 
                              - prefix[i + height][j] 
                              + prefix[i][j];
                    min_trees = min(min_trees, total);
                }
            }
        }
    }

    cout << min_trees << endl;
    return 0;
}

