            sort(exp.begin(), exp.end());
            int diff = exp[2] - exp[0];
            int likes = countLiking(groups[0], groups[1], groups[2]);
            static int min_diff = INT_MAX, max_likes = 0;
            if (diff < min_diff || (diff == min_diff && likes > max_likes)) {
                min_diff = diff;
                max_likes = likes;
            }
        }
        return;
    }

    for (int g = 0; g < 3; ++g) {
        if (groups[g].empty()) continue;
        groups[g].push_back(idx);
        backtrack(idx + 1);
        groups[g].pop_back();
    }

    for (int g = 0; g < 3; ++g) {
        if (!groups[g].empty()) continue;
        groups[g].push_back(idx);
        backtrack(idx + 1);
        groups[g].pop_back();
        break;
    }
