#include <iostream>
#include <vector>
#include <string>
#include <algorithm>
#include <cmath>

using namespace std;

const int MAXN = 51;

// Function to generate the minimal canonical form of a string under Zorg's equivalence
string minimize(const string &s) {
    int n = s.size();
    string minStr = s;
    // Generate all equivalent strings and find the minimum
    for (int i = 0; i < n; ++i) {
        string rotated = s.substr(i) + s.substr(0, i);
        string revRotated = string(rotated.rbegin(), rotated.rend());
        string flipped = "";
        for (char c : rotated)
            flipped += (c == '0') ? '1' : '0';
        string revFlipped = "";
        for (char c : revRotated)
            revFlipped += (c == '0') ? '1' : '0';
        minStr = min(minStr, rotated);
        minStr = min(minStr, revRotated);
        minStr = min(minStr, flipped);
        minStr = min(minStr, revFlipped);
    }
    return minStr;
}

// Generate all unique minimal strings according to Zorg's rules
void generateAllMinimized(int n, vector<string> &result) {
    vector<int> bits(n, 0);
    while (true) {
        string s;
        for (int b : bits)
            s += to_string(b);
        result.push_back(minimize(s));
        // Increment the binary number represented by bits
        int i = n - 1;
        while (i >= 0 && bits[i] == 1) {
            bits[i--] = 0;
        }
        if (i < 0) break;
        bits[i] = 1;
    }
}

// Sort the minimized strings in Zorg's order
bool zorgCompare(const string &a, const string &b) {
    for (int i = 0; i < a.size(); ++i) {
        if (a[i] != b[i]) {
            return a[i] < b[i]; // 0 is considered smaller than 1
        }
    }
    return true;
}

int main() {
    long long n, k;
    cin >> n >> k;

    vector<string> allStrings;
    generateAllMinimized(n, allStrings);

    // Remove duplicates
    sort(allStrings.begin(), allStrings.end(), zorgCompare);
    auto last = unique(allStrings.begin(), allStrings.end());
    allStrings.erase(last, allStrings.end());

    if (k > allStrings.size()) {
        cout << -1 << endl;
    } else {
        cout << allStrings[k - 1] << endl;
    }

    return 0;
}

