        for (int i = 0; i < n; ++i) {
            s += '0' + ((mask >> i) & 1);
        }

        string min_str = s;
        // Generate all equivalent strings and take the minimal one
        for (int i = 0; i < n; ++i) {
            string rev = "";
            for (int j = 0; j < n; ++j) {
                rev += '0' + (s[(i + j) % n] ^ 1); // color flip and rotation
            }
            if (rev < min_str) min_str = rev;
            for (int j = 0; j < n; ++j) {
                rev[j] ^= 1; // flip colors back to original
            }
            reverse(rev.begin(), rev.end());
            if (rev < min_str) min_str = rev;
