void printTiling(int n) {
    if (n == 1) {
        cout << "a\na\nb\nb\n";
        return;
    }

    if (n % 2 != 0) {
        cout << "-1\n";
        return;
    }

    vector<vector<char>> grid(4, vector<char>(n));

    char color = 'a';
    for (int i = 0; i < n; i += 2) {
        // Vertical dominoes in columns i and i+1
        grid[0][i] = color;
        grid[0][i + 1] = color;
        color++;

        grid[1][i] = color;
        grid[1][i + 1] = color;
        color++;

        grid[2][i] = color;
        grid[2][i + 1] = color;
        color++;

        grid[3][i] = color;
        grid[3][i + 1] = color;
        color++;
    }

    // Now ensure each vertical cut between columns splits at least one domino
    // We add horizontal dominoes to block the cuts
    for (int i = 0; i < n - 1; ++i) {
        if (grid[0][i] == grid[0][i + 1]) {
            continue;
        }
        grid[0][i] = color;
        grid[1][i] = color;
        color++;
    }

    for (int i = 0; i < n - 1; ++i) {
        if (grid[2][i] == grid[2][i + 1]) {
            continue;
        }
        grid[2][i] = color;
        grid[3][i] = color;
        color++;
    }

    for (int i = 0; i < 4; ++i) {
        for (int j = 0; j < n; ++j) {
            cout << grid[i][j];
        }
