#include <iostream>
#include <vector>
using namespace std;

void printPattern(int n, char c1, char c2, char c3, char c4) {
    for (int i = 0; i < n; ++i) {
        cout << c1;
        if (i % 2 == 0) cout << c2;
        else cout << c3;
        if (n > 1) {
            if (i % 2 == 0) cout << c4;
            else cout << c2;
        }
        cout << '\n';
    }
}

int main() {
    int n;
    cin >> n;

    if (n == 1) {
        cout << "-1\n";
        return 0;
    }

    if (n % 2 != 0) {
        cout << "-1\n";
        return 0;
    }

    vector<string> grid(4, string(n, ' '));
    int color = 97;

    for (int i = 0; i < n; i += 2) {
        // Place vertical dominoes in columns i and i+1
        for (int r = 0; r < 4; r += 2) {
            grid[r][i] = grid[r][i + 1] = 'a' + (color++ % 26);
            grid[r + 1][i] = grid[r + 1][i + 1] = 'a' + (color++ % 26);
        }
    }

    for (int i = 0; i < 4; ++i)
        cout << grid[i] << '\n';

    return 0;
}

