#include <iostream>
#include <vector>
#include <cmath>

using namespace std;

// Function to compute gcd using Euclidean algorithm
long long gcd(long long a, long long b) {
    while (b != 0) {
        long long temp = b;
        b = a % b;
        a = temp;
    }
    return a;
}

// Function to find the expected number of coin tosses as a fraction
pair<long long, long long> expectedTosses(int n) {
    if (n == 1)
        return {0, 1};

    vector<int> binaryLengths;
    int k = 0;
    while ((1 << k) < n) {
        k++;
    }

    // All possible lengths from k down to ceil(log2(n))
    for (int i = k; (1 << i) >= n; --i) {
        binaryLengths.push_back(i);
    }

    long long numerator = 0, denominator = 1;

    for (int l : binaryLengths) {
        long long m = 1LL << l;
        long long ways = m - n * ((m - 1) / n + 1);
        if (ways < 0)
            ways = 0;
        long long prob = m - ways;
        long long new_num = prob * (1LL << l);
        long long new_den = m * m;

        // Add to total expectation
        long long g = gcd(new_num, new_den);
        new_num /= g;
        new_den /= g;

        g = gcd(denominator, new_den);
        long long lcm = denominator * new_den / g;
        numerator = numerator * (lcm / denominator) + new_num * (lcm / new_den);
        denominator = lcm;

        // Reduce overall fraction
        g = gcd(numerator, denominator);
        numerator /= g;
        denominator /= g;
    }

    return {numerator, denominator};
}

int main() {
    int n;
    cin >> n;

    auto [a, b] = expectedTosses(n);

    cout << a << "/" << b << endl;

    return 0;
}

