#include <iostream>
#include <vector>
#include <numeric>

using namespace std;

// Function to compute the expected number of coin tosses as a fraction
pair<long long, long long> compute_expected(int n) {
    vector<int> dp(n + 1); // dp[i] is the expected number of tosses for i knights
    vector<pair<int, int>> transitions(n + 1); // transitions[i] = (a, b), meaning from state i, we can go to a or b with equal probability

    for (int i = 2; i <= n; ++i) {
        int k = 1;
        while ((1 << k) < i) {
            ++k;
        }
        int full = 1 << k;
        transitions[i] = { min(2 * (i - (full / 2)) , full - i + 1), i };
    }

    for (int i = 1; i <= n; ++i) {
        if (i == 1) {
            dp[i] = 0;
        } else if (i == 2) {
            dp[i] = 1;
        } else {
            auto [a, b] = transitions[i];
            dp[i] = 1 + (dp[a] + dp[b]) / 2;
        }
    }

    long long numerator = dp[n];
    long long denominator = 1;

    // Convert to fraction and reduce
    long long g = gcd(numerator, denominator);
    return { numerator / g, denominator / g };
}

int main() {
    int n;
    cin >> n;
    auto [a, b] = compute_expected(n);
    cout << a << "/" << b << endl;
    return 0;
}

