using namespace std;

// Function to compute GCD
int gcd(int a, int b) {
    while (b != 0) {
        int temp = b;
        b = a % b;
        a = temp;
    }
    return a;
}

// Function to reduce the fraction
pair<int, int> reduce(pair<int, int>& frac) {
    int g = gcd(frac.first, frac.second);
    return {frac.first / g, frac.second / g};
}

// Memoization for expected value calculation
vector<pair<int, int>> memo;

// Recursive function to calculate expected tosses
pair<int, int> expected_tosses(int n) {
    if (n == 1) return {0, 1}; // Base case: no toss needed

    if (memo[n].first != -1 && memo[n].second != -1)
        return memo[n];

    pair<int, int> res = {0, 1};

    // Try all possible splits of n into two groups
    for (int k = 1; k < n; ++k) {
        pair<int, int> left = expected_tosses(k);
        pair<int, int> right = expected_tosses(n - k);

        // Compute 1 + E(left) * (k/n) + E(right) * ((n-k)/n)
        pair<int, int> term1 = {1, 1};
        pair<int, int> term2 = reduce({left.first * k, left.second * n});
        pair<int, int> term3 = reduce({right.first * (n - k), right.second * n});

        // Add term2 and term3
        int a = term2.first * term3.second + term3.first * term2.second;
        int b = term2.second * term3.second;
        pair<int, int> sum_terms = reduce({a, b});

        // Add 1 to sum_terms
        a = sum_terms.first + term1.first * sum_terms.second;
        b = sum_terms.second;
        pair<int, int> total = reduce({a, b});

        // Compare with current result and choose minimum
        double cur_val = (double)res.first / res.second;
        double new_val = (double)total.first / total.second;
        if (new_val < cur_val) {
            res = total;
        }
    }

    memo[n] = res;
    return res;
}

int main() {
    int n;
    cin >> n;

    memo.assign(n + 1, {-1, -1});
    pair<int, int> result = expected_tosses(n);

    cout << result.first << "/" << result.second << endl;
    return 0;
}

