#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

// Function to compute the GCD of two numbers
int gcd(int a, int b) {
    while (b != 0) {
        int temp = b;
        b = a % b;
        a = temp;
    }
    return a;
}

// Function to add two fractions: a/b + c/d
pair<int, int> addFractions(pair<int, int> f1, pair<int, int> f2) {
    int numerator = f1.first * f2.second + f2.first * f1.second;
    int denominator = f1.second * f2.second;
    int g = gcd(numerator, denominator);
    return {numerator / g, denominator / g};
}

// Function to multiply a fraction by a scalar
pair<int, int> multiplyFractionScalar(pair<int, int> f, int k) {
    int numerator = f.first * k;
    int denominator = f.second;
    int g = gcd(numerator, denominator);
    return {numerator / g, denominator / g};
}

int main() {
    int n;
    cin >> n;

    vector<pair<int, int>> dp(n + 1); // dp[i] stores expected tosses for i knights as a fraction

    dp[1] = {0, 1}; // 0 tosses needed if only one knight
    dp[2] = {1, 1}; // 1 toss needed if two knights

    for (int i = 3; i <= n; ++i) {
        int k = 1;
        int total = 0;
        pair<int, int> res = {0, 1};

        while (true) {
            int ways = 1 << k;
            if (ways > i)
                break;

            int remainder = ways % i;
            int full_blocks = ways / i;

            pair<int, int> term = multiplyFractionScalar(dp[remainder], full_blocks);
            pair<int, int> prob = {full_blocks, ways};
            pair<int, int> weightedTerm = {term.first * prob.first, term.second * prob.second};

            res = addFractions(res, weightedTerm);

            total += full_blocks;

            k++;
        }

        pair<int, int> additional = {k, 1};
        res = addFractions(res, additional);

        int remaining = (1 << k) - total;
        pair<int, int> extra = {remaining, 1 << k};
        res = addFractions(res, extra);

        dp[i] = res;
    }

    cout << dp[n].first << "/" << dp[n].second << endl;
    return 0;
}

