using namespace std;

struct Fraction {
    long long numerator;
    long long denominator;

    Fraction(long long num, long long den) : numerator(num), denominator(den) {}

    void reduce() {
        long long g = __gcd(numerator, denominator);
        numerator /= g;
        denominator /= g;
    }
};

Fraction operator+(const Fraction& a, const Fraction& b) {
    long long num = a.numerator * b.denominator + b.numerator * a.denominator;
    long long den = a.denominator * b.denominator;
    return Fraction(num, den);
}

Fraction operator*(const Fraction& a, const Fraction& b) {
    long long num = a.numerator * b.numerator;
    long long den = a.denominator * b.denominator;
    return Fraction(num, den);
}

void dfs(int n, vector<Fraction>& dp, vector<vector<int>>& choices) {
    if (dp[n].numerator != -1) return;

    if (n == 1) {
        dp[1] = Fraction(0, 1);
        choices[1] = {0};
        return;
    }

    dp[n] = Fraction(0, 1);
    int best_k = 0;
    for (int k = 1; (1 << k) >= n; ++k) {
        int m = (1 << k) - n;
        Fraction expected = Fraction(k, 1) + Fraction(m, 1 << k) * dp[m];
        if (best_k == 0 || expected.numerator * dp[best_k].denominator < dp[best_k].numerator * expected.denominator) {
            dp[n] = expected;
            best_k = k;
        }
    }

    choices[n] = {};
    for (int i = 0; i < best_k; ++i)
        choices[n].push_back(0);

    int m = (1 << best_k) - n;
    if (m > 0) {
        dfs(m, dp, choices);
        for (auto x : choices[m])
            choices[n].push_back(x + best_k);
    }
}

