    int n;
    cin >> n;

    vector<Fraction> dp(n + 1);
    for (int i = 0; i <= n; ++i)
        dp[i] = Fraction(-1, 1);

    vector<vector<int>> choices(n + 1);

    dfs(n, dp, choices);

    dp[n].reduce();
    cout << dp[n].numerator << "/" << dp[n].denominator << endl;

