// Recursive function to compute expected number of tosses
pair<int, int> expectedTosses(int n, vector<pair<int, int>>& dp) {
    if (n == 1) return {0, 1}; // base case: no toss needed for 1 person
    if (n == 2) return {1, 1}; // base case: one toss

    if (dp[n].first != -1 && dp[n].second != -1)
        return dp[n];

    int minExpected = 1 << 30; // big enough initial value
    int bestDenominator = 1;

    for (int i = 1; i < n; ++i) {
        auto left = expectedTosses(i, dp);
        auto right = expectedTosses(n - i, dp);

        // Expected tosses is 1 + E(left)/2 + E(right)/2
        int num = left.first * right.second + right.first * left.second;
        int den = left.second * right.second;
        int newNum = 1 * den + num;
        int newDen = 2 * den;

        // Reduce and compare
        auto [a, b] = reduceFraction(newNum, newDen);
        if (a * bestDenominator < minExpected * b) {
            minExpected = a;
            bestDenominator = b;
        }
    }

    dp[n] = reduceFraction(minExpected, bestDenominator);
    return dp[n];
}

int main() {
    int n;
    cin >> n;

    vector<pair<int, int>> dp(n + 1, {-1, -1});
    auto [a, b] = expectedTosses(n, dp);

