using namespace std;

typedef long long ll;

// Function to compute GCD
ll gcd(ll a, ll b) {
    while (b != 0) {
        ll temp = b;
        b = a % b;
        a = temp;
    }
    return a;
}

// Function to add two fractions and reduce
pair<ll, ll> addFraction(pair<ll, ll>& a, pair<ll, ll>& b) {
    ll numerator = a.first * b.second + b.first * a.second;
    ll denominator = a.second * b.second;
    ll g = gcd(numerator, denominator);
    return {numerator / g, denominator / g};
}

// Memoization for expected tosses for n knights
map<int, pair<ll, ll>> memo;

pair<ll, ll> solve(int n) {
    if (n == 1) return {0, 1}; // No toss needed if only one knight
    if (memo.find(n) != memo.end()) return memo[n];

    pair<ll, ll> res = {0, 1};
    for (int k = 1; k < n; ++k) {
        // For each split into k and n - k parts
        int m = k;
        int l = n - k;
        pair<ll, ll> p1 = solve(m);
        pair<ll, ll> p2 = solve(l);

        // Probability of choosing first part: 2^(-s), where s is the number of bits in binary representation of min(m,l)
        int bits = 0;
        int x = min(m, l);
        while (x > 0) {
            x >>= 1;
            bits++;
        }

        ll prob_num = 1;
        ll prob_den = 1LL << bits;

        // Total expected value for this split
        pair<ll, ll> term1 = {prob_num, prob_den};
        pair<ll, ll> term2 = addFraction(p1, p2);
        pair<ll, ll> term3 = {term2.first, term2.second};
        pair<ll, ll> term = {term1.first * term3.first, term1.second * term3.second};

        // Add to result
        res = addFraction(res, term);
    }

    // Average over all splits (divide by (n-1))
    res.first *= 1;
    res.second *= (n - 1);
    ll g = gcd(res.first, res.second);
    res.first /= g;
    res.second /= g;

    memo[n] = res;
    return res;
}

int main() {
    int n;
    cin >> n;
    pair<ll, ll> ans = solve(n);
    cout << ans.first << "/" << ans.second << endl;
    return 0;
}

