    int a, b, h;
};

bool compare(const Ring &r1, const Ring &r2) {
    if (r1.b != r2.b)
        return r1.b > r2.b;
    return r1.a > r1.a;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);

    int n;
    cin >> n;

    vector<Ring> rings(n);
    for (int i = 0; i < n; ++i)
        cin >> rings[i].a >> rings[i].b >> rings[i].h;

    sort(rings.begin(), rings.end(), compare);

    vector<long long> dp(n);
    dp[0] = rings[0].h;

    for (int i = 1; i < n; ++i) {
        dp[i] = rings[i].h;
        for (int j = 0; j < i; ++j) {
            if (rings[j].a < rings[i].b && rings[j].b >= rings[i].b) {
                dp[i] = max(dp[i], dp[j] + rings[i].h);
            }
        }
    }

    cout << *max_element(dp.begin(), dp.end()) << endl;
    return 0;
}

