    int count_zero = 0;
    for (char c : n_str) {
        if (c == '0') count_zero++;
    }

    if (count_zero >= k) {
        cout << n_str.length() - k << endl;
        return 0;
    }

    // Try to find k zeros from the end
    int zero_count = 0;
    int digits_to_remove = 0;
    for (int i = n_str.length() - 1; i >= 0; --i) {
        if (n_str[i] == '0') {
            zero_count++;
            if (zero_count == k) break;
        } else {
            digits_to_remove++;
        }
    }

    if (zero_count == k) {
        cout << digits_to_remove << endl;
    } else {
        cout << -1 << endl; // This line is theoretically unreachable due to problem statement guarantee
    }

    return 0;
