#include <iostream>
#include <vector>
#include <algorithm>
#include <climits>

using namespace std;

bool canFit(int a, int b, long long h, long long w) {
    return (h >= a && w >= b) || (h >= b && w >= a);
}

int main() {
    int required_a, required_b, h, w, n;
    cin >> required_a >> required_b >> h >> w >> n;
    vector<int> extensions(n);
    for (int i = 0; i < n; ++i) {
        cin >> extensions[i];
    }

    if (canFit(required_a, required_b, h, w)) {
        cout << 0 << endl;
        return 0;
    }

    sort(extensions.begin(), extensions.end(), greater<int>());

    for (int k = 1; k <= n; ++k) {
        vector<int> best_k;
        for (int i = 0; i < k; ++i) {
            best_k.push_back(extensions[i]);
        }

        int m = k;
        vector<long long> multipliers(best_k.begin(), best_k.end());
        sort(multipliers.begin(), multipliers.end());

        for (int mask = 0; mask < (1 << m); ++mask) {
            long long h1 = h, w1 = w;
            for (int i = 0; i < m; ++i) {
                if (mask & (1 << i)) {
                    h1 *= multipliers[i];
                } else {
                    w1 *= multipliers[i];
                }
            }
            if (canFit(required_a, required_b, h1, w1)) {
                cout << k << endl;
                return 0;
            }
        }
    }

    cout << -1 << endl;
    return 0;
}

