bool canFit(int a, int b, int h, int w) {
    return (h >= a && w >= b) || (h >= b && w >= a);
}

int main() {
    int targetA, targetB, h, w, n;
    cin >> targetA >> targetB >> h >> w >> n;

    if (canFit(targetA, targetB, h, w)) {
        cout << 0 << endl;
        return 0;
    }

    vector<int> multipliers;
    for (int i = 0; i < n; ++i) {
        int x;
        cin >> x;
        multipliers.push_back(x);
    }

    sort(multipliers.begin(), multipliers.end());
    reverse(multipliers.begin(), multipliers.end());

    for (int k = 1; k <= n; ++k) {
        vector<int> bestK;
        for (int i = 0; i < k; ++i) {
            bestK.push_back(multipliers[i]);
        }
        sort(bestK.begin(), bestK.end());

        for (int mask = 0; mask < (1 << k); ++mask) {
            long long h1 = h, w1 = w;
            for (int i = 0; i < k; ++i) {
