#include <iostream>
#include <vector>
#include <cmath>
#include <iomanip>

using namespace std;

// Function to compute variance of the sample
double computeVariance(const vector<int>& data) {
    double mean = 0.0;
    for (int val : data)
        mean += val;
    mean /= data.size();

    double var = 0.0;
    for (int val : data)
        var += (val - mean) * (val - mean);
    var /= data.size();
    return var;
}

// Function to determine distribution type based on variance
string determineDistribution(double variance, int n_samples) {
    // Poisson distribution has variance equal to the mean.
    // For Uniform distribution over [0, 2P], variance is ((2P + 1)^2 - 1)/12 ≈ (4P^2)/12 = P^2/3
    // So for uniform, variance should be significantly larger than mean.

    // Estimate mean from the data
    double mean = 0.0;
    for (int val : data)
        mean += val;
    mean /= n_samples;

    // Expected variance for uniform is approx (mean * 3), since mean ~ P
    double expectedUniformVariance = mean * 3;

    if (variance <= expectedUniformVariance)
        return "poisson";
    else
        return "uniform";
}

int main() {
    int V;
    cin >> V;

    for (int v = 0; v < V; ++v) {
        vector<int> responses(250);
        for (int i = 0; i < 250; ++i)
            cin >> responses[i];

        double variance = computeVariance(responses);
        string result = determineDistribution(variance, 250);

        cout << result << endl;
    }

    return 0;
}

