    vector<int> answers(n);
    for (int i = 0; i < n; ++i) {
        cin >> answers[i];
    }

    // Count frequency of each answer
    map<int, int> freq;
    for (int ans : answers) {
        freq[ans]++;
    }

    // Find the most frequent answer(s)
    int max_freq = 0;
    vector<int> modes;
    for (const auto& [val, count] : freq) {
        if (count > max_freq) {
            max_freq = count;
            modes.clear();
            modes.push_back(val);
        } else if (count == max_freq) {
            modes.push_back(val);
        }
    }

    // Try all possible modes as potential lambda or midpoint of uniform distribution
    int best_estimate = -1;
    double min_error = 1e9;

    for (int mode : modes) {
        // Assume Poisson with lambda = mode
        double expected_poisson = static_cast<double>(n) * exp(-mode) * pow(mode, mode) / tgamma(mode + 1);
        double error_poisson = abs(expected_poisson - freq[mode]);

        // Assume Uniform distribution from a to b
        // Try all possible intervals that include the current mode and have at least one value in the data
        for (int a = 0; a <= mode; ++a) {
            for (int b = mode; b <= *max_element(answers.begin(), answers.end()); ++b) {
                if (a > b) continue;
                int size = b - a + 1;
                if (size == 0 || n % size != 0) continue;
                int expected_uniform = n / size;
                if (abs(expected_uniform - freq[a]) > 2 || abs(expected_uniform - freq[b]) > 2) continue;
                bool valid = true;
                for (int i = a; i <= b; ++i) {
                    if (freq.count(i) && abs(freq[i] - expected_uniform) > 2) {
                        valid = false;
                        break;
                    }
                }
                if (!valid) continue;

                int mid = (a + b) / 2;
                double error_uniform = abs(static_cast<double>(n) / size - freq[mode]);
                if (error_uniform < min_error) {
                    min_error = error_uniform;
                    best_estimate = mid;
                }
            }
        }

        if (error_poisson < min_error) {
            min_error = error_poisson;
            best_estimate = mode;
        }
    }

    cout << best_estimate << endl;
    return 0;
