    vector<int> answers(n);
    for (int i = 0; i < n; ++i) {
        cin >> answers[i];
    }

    // Count frequency of each answer
    map<int, int> freq;
    for (int ans : answers) {
        freq[ans]++;
    }

    // Find the most frequent answer(s)
    int max_freq = 0;
    vector<int> modes;
    for (const auto& [val, count] : freq) {
        if (count > max_freq) {
            max_freq = count;
            modes.clear();
            modes.push_back(val);
        } else if (count == max_freq) {
            modes.push_back(val);
        }
    }

    // Try all possible modes as estimates and find the one with smallest chi-square
    double min_chi2 = 1e9;
    int best_estimate = -1;

    for (int mode : modes) {
        // Assume Poisson distribution with lambda = mode
        map<int, double> expected_poisson;
        double total = 0.0;
        for (int k = 0; k <= *max_element(answers.begin(), answers.end()) + 5; ++k) {
            double p = exp(-mode);
            double term = 1.0;
            for (int i = 1; i <= k; ++i) {
                term *= mode / i;
            }
            p *= term;
            expected_poisson[k] = p * n;
            total += p;
        }

        // Normalize expected frequencies to sum up to n
        for (auto& [key, val] : expected_poisson) {
            val /= total;
        }

        // Compute chi-square statistic
        double chi2 = 0.0;
        for (const auto& [val, count] : freq) {
            double e = expected_poisson[val];
            if (e == 0) continue;
            chi2 += ((count - e) * (count - e)) / e;
        }

        if (chi2 < min_chi2) {
            min_chi2 = chi2;
            best_estimate = mode;
        }
    }

    cout << best_estimate << endl;
    return 0;
}

