using namespace std;

// Function to calculate the mean of a vector
double mean(const vector<int>& data) {
    double sum = 0;
    for (int x : data) {
        sum += x;
    }
    return sum / data.size();
}

// Function to calculate variance
double variance(const vector<int>& data, double mu) {
    double var = 0;
    for (int x : data) {
        var += (x - mu) * (x - mu);
    }
    return var / data.size();
}

// Estimate population based on Poisson or Uniform distribution
int estimate_population(double mu, double var) {
    if (abs(mu - var) < 1e-6) {
        // Poisson distribution: mean is equal to lambda which is also the expected value
        return round(mu);
    } else {
        // Uniform distribution: mean = (a + b) / 2
        // Variance = ((b - a + 1)^2 - 1) / 12
        // Solve for a and b
        int N = data.size();
        double sqrt_var = sqrt(12.0 * var + 1.0);
        int k = static_cast<int>(round(sqrt_var));
        int P = static_cast<int>(round(2 * mu - k + 1));
        return max(1, P); // Ensure at least one person
    }
}

int main() {
    int T;
    cin >> T;

    for (int t = 0; t < T; ++t) {
        int N;
        cin >> N;
        vector<int> data(N);
        for (int i = 0; i < N; ++i) {
            cin >> data[i];
        }

        double mu = mean(data);
        double var = variance(data, mu);

        int estimate = estimate_population(mu, var);
        cout << estimate << endl;
    }

    return 0;
}

