    for (int x : data)
        var += (x - mu) * (x - mu);
    return var / data.size();
}

// Poisson distribution: mean == variance
bool is_poisson(double mu, double var, double threshold = 1e-5) {
    return abs(mu - var) < threshold;
}

// For uniform distribution on [a, b], mean = (a + b)/2 and variance = ((b - a + 1)^2 - 1) / 12
// Try all possible integer intervals [a, b] that match the sample mean and variance
int estimate_uniform(double mu, double var) {
    // Try possible integer bounds for uniform distribution
    for (int a = 0; a <= 1000; ++a) {
        for (int b = a; b <= 1000; ++b) {
            double expected_mu = (a + b) / 2.0;
            double expected_var = ((b - a + 1) * (b - a + 1) - 1.0) / 12.0;
            if (abs(expected_mu - mu) < 1e-5 && abs(expected_var - var) < 1e-5) {
                return (b + a + 1) / 2; // midpoint of the interval as population estimate
            }
        }
    }
    return round(mu); // fallback
