            double dx = circles[i].x - circles[j].x;
            double dy = circles[i].y - circles[j].y;
            double dist = sqrt(dx * dx + dy * dy);
            if (dist + 1e-8 < circles[i].r - circles[j].r) {
                parent[i] = j;
                break;
            }
        }
    }
    return parent;
}

vector<vector<int>> getChildrenList(vector<int>& parent) {
    int n = parent.size();
    vector<vector<int>> children(n);
    for (int i = 0; i < n; ++i) {
        if (parent[i] != -1)
            children[parent[i]].push_back(i);
    }
    return children;
}

