    return M_PI * r * r;
}

pair<double, double> dfs(int node, vector<vector<int>>& children, vector<Circle>& circles) {
    double in = 0.0, out = 0.0;
    for (int child : children[node]) {
        auto [cIn, cOut] = dfs(child, children, circles);
        in += max(cIn, cOut);
        out += max(cIn, cOut);
    }
    double area = areaOfCircle(circles[node].r);
    double take = area - in;
    double notTake = out;
    return {take, notTake};
}

