    ios::sync_with_stdio(false);
    cin.tie(0);

    int n, m;
    cin >> n >> m;

    precompute_factorials(n, MOD);

    long long ans = 1;
    for (int i = 0; i < m; ++i) {
        ans = ans * (n + i) % MOD;
    }

